-- 037: Zwölf neue Geschichten (6 daheim, 4 in Städten, 2 Gastgeschichten). Erzeugt von quests/g3_sql.py
insert into public.quest_templates (id, titel, beschreibung, kurz, art, schwierigkeit, rollen, def, fundort)
select e->>'id', e->>'titel', e->>'kurz', e->>'kurz', 'haupt', (e->>'schwer')::int, '{}'::jsonb, e->'def', e->>'fundort' from jsonb_array_elements($q$[{"id": "g_klamm", "titel": "Der Zoll an der Klamm", "kurz": "Söldner sperren den Weg nach Süden. Einer von ihnen ist ein Junge, den das Dorf einmal verstoßen hat.", "schwer": 2, "fundort": null, "def": {"start": "start", "szenen": {"start": {"ort": "dorf", "text": "Ein Bauer kommt mit blutiger Lippe ins Dorf. An der Klamm, wo der Weg nach Süden durch die Felsen führt, hat sich ein Söldnertrupp eingenistet. Wer durch will, zahlt – mit Korn, mit Werkzeug, mit allem. „Einer von denen“, sagt der Bauer und spuckt aus, „ist der junge Lutz. Der vom Gerberhof. Den ihr im Hungerwinter weggejagt habt.“", "optionen": [{"text": "Sofort zur Klamm aufbrechen", "weiter": "weg"}, {"text": "Erst die Alten nach Lutz fragen", "weiter": "lutz_frage"}, {"text": "Waffen und Vorräte packen, dann los", "weiter": "weg", "ergebnis": "Du schärfst die Klinge, packst Brot und Verbandszeug. Wer weiß, wie lange das dauert.", "folgen": {"flag": ["vorbereitet"]}}]}, "lutz_frage": {"ort": "dorf", "text": "Die alte Wäscherin wischt sich die Hände ab, bevor sie redet. „Der Gerberhof hatte drei Mäuler und kein Korn. Der Rat hat beschlossen: Wer nicht arbeiten kann, kriegt nichts aus dem Speicher. Lutz’ Mutter war krank. Sie ist im Februar gestorben. Lutz war vierzehn.“ Sie sieht dich nicht an. „Ich hab dafür gestimmt. Wir hatten selbst Kinder.“", "optionen": [{"text": "„Ihr habt ihn verhungern lassen.“", "weiter": "weg", "ergebnis": "„Wir haben die anderen leben lassen“, sagt sie leise. „Das ist nicht dasselbe. Aber es fühlt sich so an.“", "folgen": {"flag": ["kennt_schuld"]}}, {"text": "Schweigend nicken und aufbrechen", "weiter": "weg", "folgen": {"flag": ["kennt_schuld"]}}]}, "weg": {"ort": "wald", "text": "Der Weg nach Süden steigt an. Die Felsen rücken zusammen, das Licht wird grau.", "reise": {"minuten": 70, "weiter": "klamm", "text": "Du gehst {mit} Richtung Klamm.", "begegnung": {"chance": 0.5, "szenen": ["b_fluechtling"]}}}, "b_fluechtling": {"ort": "wald", "text": "Eine Frau mit zwei Kindern kommt dir entgegen, barfuß. „Sie haben uns die Schuhe genommen“, sagt sie. „Und den Esel. Der Anführer hat gelacht dabei.“ Das ältere Kind starrt auf deine Stiefel.", "optionen": [{"text": "Dem Kind deine Ersatzschuhe geben", "weiter": "klamm", "ergebnis": "Die Schuhe sind viel zu groß. Das Kind läuft trotzdem, als hätte es Flügel.", "folgen": {"chronik": ["klamm_schuhe", "Ich habe einem Kind an der Klamm meine Schuhe gegeben."]}}, {"text": "Fragen, wie viele es sind", "weiter": "klamm", "ergebnis": "„Sieben. Vielleicht acht. Und einer, der nicht dazugehört. Jung. Hat uns heimlich Brot zugesteckt.“", "folgen": {"flag": ["lutz_gut"]}}]}, "klamm": {"ort": "berg", "text": "Ein umgestürzter Karren versperrt den Weg, dahinter ein Feuer. Sieben Männer in zusammengestückelten Rüstungen. Ihr Anführer, ein breiter Kerl mit verbranntem Ohr, steht auf. „Zoll“, sagt er nur. Hinter ihm, am Rand, ein Junge mit zu großem Helm. Lutz. Er erkennt dich nicht – oder tut so.", "optionen": [{"text": "„Ihr habt heute schon genug genommen. Zieht weiter.“", "tag": "[Einschüchtern]", "probe": {"id": "einschuechtern", "dc": 14}, "erfolg": {"text": "Der Anführer mustert dich lange. Dann lacht er. „Mut hast du. Aber Mut ist kein Zoll.“ Immerhin – seine Leute sind unruhig geworden.", "weiter": "verhandeln", "folgen": {"flag": ["eingeschuechtert"]}}, "misserfolg": {"text": "Gelächter. „Hört euch den an!“ Zwei Männer ziehen ihre Klingen.", "weiter": "kampf"}}, {"text": "Lutz direkt ansprechen: „Ich weiß, was das Dorf dir angetan hat.“", "tag": "[Menschenkenntnis]", "probe": {"id": "menschenkenntnis", "dc": 12}, "erfolg": {"text": "Lutz zuckt zusammen. Sein Blick geht zu dir, dann zum Anführer – Angst. Er ist nicht freiwillig hier. Nicht mehr.", "weiter": "lutz_blick", "folgen": {"flag": ["lutz_zweifel"]}}, "misserfolg": {"text": "Lutz verzieht keine Miene. „Ich kenn dich nicht“, sagt er. Aber seine Hand zittert am Speer.", "weiter": "verhandeln"}, "wenn": {"flag": "kennt_schuld"}}, {"text": "Den Zoll zahlen und durchgehen", "weiter": "zahlen"}, {"text": "Ohne Worte angreifen", "tag": "[Kampf]", "weiter": "kampf"}]}, "lutz_blick": {"ort": "berg", "text": "Der Anführer hat es bemerkt. Er legt Lutz eine schwere Hand auf die Schulter. „Der Junge gehört zu uns. Er schuldet uns sein Leben. Ohne uns wär er im Schnee verreckt – genau wie seine Mutter. Nicht wahr, Lutz?“ Lutz sagt nichts.", "optionen": [{"text": "„Komm mit mir zurück, Lutz. Ich sorge dafür, dass du einen Platz bekommst.“", "tag": "[Überreden]", "probe": {"id": "ueberreden", "dc": 13}, "erfolg": {"text": "Lutz sieht dich an. „Versprichst du das? Vor allen?“ Du nickst. Langsam nimmt er den Helm ab. Der Anführer flucht – und zieht das Schwert.", "weiter": "kampf_lutz", "folgen": {"flag": ["lutz_kommt"]}}, "misserfolg": {"text": "„Einen Platz?“ Lutz lacht bitter. „Den hatte ich schon mal.“ Er tritt einen Schritt zurück, zu den anderen.", "weiter": "verhandeln"}}, {"text": "„Dann schuldest du ihnen nichts mehr. Ich zahle seine Schuld.“", "weiter": "freikauf"}]}, "freikauf": {"ort": "berg", "text": "„Seine Schuld?“ Der Anführer grinst. „Fünfzig Scheite Holz. Und dein Messer.“ Ein lächerlicher Preis – oder eine Prüfung, ob du es ernst meinst.", "optionen": [{"text": "Zahlen. Holz und Messer.", "wenn": {"holz": 50}, "weiter": "ende_freikauf", "folgen": {"holz": -50, "flag": ["lutz_kommt"]}}, {"text": "„Das habe ich nicht dabei. Aber im Dorf.“", "weiter": "verhandeln", "ergebnis": "„Im Dorf.“ Er spuckt ins Feuer. „Das sagen alle.“"}]}, "verhandeln": {"ort": "berg", "text": "Der Anführer verschränkt die Arme. „Also. Was ist dir der Weg wert?“ Seine Männer haben die Hände an den Waffen.", "optionen": [{"text": "Den Zoll herunterhandeln und dafür sorgen, dass sie weiterziehen", "tag": "[Feilschen]", "probe": {"id": "feilschen", "dc": 13}, "erfolg": {"text": "Ihr einigt euch auf ein Fass Korn – und sein Wort, dass sie bis zum Neumond die Klamm verlassen. Ein Wort, das nicht viel wert sein mag. Aber es ist eins.", "weiter": "ende_handel"}, "misserfolg": {"text": "„Du feilschst wie ein Krämer“, knurrt er. „Ich mag keine Krämer.“", "weiter": "kampf"}}, {"text": "„Dann eben so.“ Die Klinge ziehen.", "tag": "[Kampf]", "weiter": "kampf"}]}, "zahlen": {"ort": "berg", "text": "Du legst ab, was du hast. Der Anführer wiegt es in der Hand. „Klug. Die Klugen werden alt.“ Als du an Lutz vorbeigehst, flüstert er, fast unhörbar: „Sie wollen nächste Woche ins Dorf. Wenn alle auf dem Feld sind.“", "optionen": [{"text": "Umkehren und das Dorf warnen", "weiter": "ende_warnung", "folgen": {"flag": ["gewarnt"]}}, {"text": "Lutz zuflüstern: „Komm heute Nacht zum alten Grenzstein.“", "weiter": "nacht"}]}, "nacht": {"ort": "wald", "text": "Der Grenzstein, Mitternacht. Du wartest lange. Dann Schritte – Lutz, allein, mit einem Bündel. „Wenn sie merken, dass ich weg bin, kommen sie sofort. Nicht nächste Woche.“", "optionen": [{"text": "„Dann sind wir vorbereitet.“ Mit ihm ins Dorf eilen.", "weiter": "ende_nacht", "folgen": {"flag": ["lutz_kommt"]}}]}, "kampf": {"ort": "berg", "text": "Stahl blitzt im Feuerschein. Die Söldner fächern sich auf, der Anführer brüllt Befehle.", "gefahr": true, "minispiel": {"art": "kampf", "schwer": 2, "titel": "Kampf an der Klamm", "gegner": "banditen", "dauer": 420, "kampfort": "berg", "erfolg": {"text": "Der letzte Söldner flieht in die Felsen. Der Anführer liegt im Staub, lebt aber. Lutz steht da, den Speer gesenkt, und weiß nicht, wohin.", "weiter": "nach_kampf"}, "misserfolg": {"text": "Ein Schlag gegen den Kopf, Dunkelheit. Als du aufwachst, sind sie fort – mit allem, was du hattest. Und mit Lutz.", "weiter": "ende_niederlage", "folgen": {"gefahr": 2}}}, "optionen": []}, "kampf_lutz": {"ort": "berg", "text": "Lutz steht neben dir, den Speer in zitternden Händen. Gegen seine alten Kameraden.", "gefahr": true, "minispiel": {"art": "kampf", "schwer": 2, "titel": "Rücken an Rücken", "gegner": "banditen", "dauer": 360, "kampfort": "berg", "erfolg": {"text": "Sie fliehen. Lutz sinkt auf die Knie und übergibt sich. Dann sieht er dich an. „Du hast es versprochen. Vor allen.“", "weiter": "ende_lutz"}, "misserfolg": {"text": "Ihr werdet zurückgedrängt, aber sie verfolgen euch nicht. Lutz blutet am Arm. „Weiter“, keucht er. „Nur weg hier.“", "weiter": "ende_lutz", "folgen": {"gefahr": 1}}}, "optionen": []}, "nach_kampf": {"ort": "berg", "text": "Der Anführer hustet Blut. „Mach schon“, sagt er. Lutz schaut dich an, als ob du jetzt entscheidest, was für ein Mensch er werden soll.", "optionen": [{"text": "Den Anführer laufen lassen. „Komm nie wieder.“", "weiter": "ende_gnade"}, {"text": "Ihn gefesselt ins Dorf bringen, damit der Rat richtet", "weiter": "ende_gericht"}, {"text": "Lutz die Wahl lassen", "weiter": "lutz_wahl"}]}, "lutz_wahl": {"ort": "berg", "text": "Lutz steht lange über dem Mann, der ihm Brot und Prügel gegeben hat. Dann wirft er den Speer weg. „Ich will nicht so werden wie ihr. Wie ihr alle.“ Er meint auch das Dorf.", "optionen": [{"text": "Ihm die Hand reichen", "weiter": "ende_lutz"}]}, "ende_lutz": {"ort": "dorf", "text": "Im Dorf wird getuschelt, als du mit Lutz zurückkommst. Die alte Wäscherin geht als Erste auf ihn zu. Sie sagt nichts, sie drückt ihm nur einen Laib Brot in die Hand. Er nimmt ihn. Ob das reicht, wird sich zeigen. Aber es ist ein Anfang.", "ende": true, "folgen": {"chronik": ["klamm_lutz", "Ich habe Lutz vom Gerberhof nach Hause gebracht. Das Dorf schuldet ihm mehr als ein Brot."], "beute": {"stufe": 2, "text": "Lutz gibt dir das Einzige, was er aus seiner Söldnerzeit behalten will:"}, "begleiter_sym": 4}}, "ende_freikauf": {"ort": "dorf", "text": "Lutz geht neben dir her, schweigend, bis das Dorf in Sicht kommt. Dann bleibt er stehen. „Warum?“ Du hast keine gute Antwort. Vielleicht, weil jemand dafür bezahlen sollte, was im Hungerwinter passiert ist. Vielleicht du.", "ende": true, "folgen": {"chronik": ["klamm_freikauf", "Ich habe Lutz freigekauft. Fünfzig Scheite und ein Messer – billiger als ein schlechtes Gewissen."]}}, "ende_handel": {"ort": "dorf", "text": "Das Fass Korn tut weh. Aber niemand ist gestorben. Als du zurückblickst, steht Lutz am Feuer und schaut dir nach. Du wirst nie erfahren, ob er dich erkannt hat.", "ende": true, "folgen": {"dorf": {"nahrung": -20}, "chronik": ["klamm_handel", "Ich habe an der Klamm verhandelt statt zu kämpfen. Lutz ist geblieben, wo er war."]}}, "ende_warnung": {"ort": "dorf", "text": "Das Dorf stellt Wachen auf, Tag und Nacht. Als die Söldner kommen, finden sie verschlossene Tore und Fackeln. Sie ziehen ab. Einer bleibt zurück und wirft etwas über den Zaun: einen zu großen Helm.", "ende": true, "folgen": {"chronik": ["klamm_warnung", "Lutz hat uns gewarnt. Er ist bei den Söldnern geblieben – oder sie haben ihn nicht gehen lassen."], "beute": {"stufe": 1, "text": "Im Helm steckt etwas, eingewickelt in ein Tuch:"}}}, "ende_nacht": {"ort": "dorf", "text": "Sie kommen im Morgengrauen und finden ein wachendes Dorf. Nach kurzem Gefecht ziehen sie ab. Lutz hat die ganze Zeit neben dem Tor gestanden, kreidebleich. Danach redet zum ersten Mal seit Jahren jemand mit ihm, als gehöre er dazu.", "ende": true, "folgen": {"chronik": ["klamm_nacht", "Lutz ist nachts zu mir gekommen. Er hat das Dorf gerettet, das ihn verstoßen hat."], "beute": {"stufe": 1}}}, "ende_gnade": {"ort": "dorf", "text": "Der Anführer humpelt davon. Lutz kommt mit dir, aber er redet den ganzen Weg kein Wort. Vielleicht hätte er sich etwas anderes gewünscht. Vielleicht genau das.", "ende": true, "folgen": {"chronik": ["klamm_gnade", "Ich habe den Söldnerführer laufen lassen. Gnade oder Dummheit – das wird sich zeigen."]}}, "ende_gericht": {"ort": "dorf", "text": "Der Rat verurteilt den Söldner zur Arbeit im Steinbruch. Gerecht, sagen die einen. Die anderen sagen, der Rat habe sich schon einmal geirrt, im Hungerwinter. Lutz sitzt in der hintersten Reihe und hört zu.", "ende": true, "folgen": {"chronik": ["klamm_gericht", "Ich habe den Söldnerführer vor den Rat gebracht. Das Dorf hat gerichtet – und sich selbst dabei zugesehen."], "beute": {"stufe": 1}}}, "ende_niederlage": {"ort": "dorf", "text": "Mit leeren Händen und dröhnendem Schädel kehrst du heim. Die Klamm bleibt gesperrt, bis die Söldner von selbst weiterziehen. Manchmal verliert man. Wichtig ist, was man daraus macht.", "ende": true, "folgen": {"chronik": ["klamm_niederlage", "Ich habe an der Klamm verloren."]}}}}}, {"id": "g_moor", "titel": "Was im Moor heult", "kurz": "Etwas reißt Schafe am Moor. Das Dorf spricht von einem Werwolf. Die Spuren erzählen etwas anderes.", "schwer": 2, "fundort": null, "def": {"start": "start", "szenen": {"start": {"ort": "dorf", "text": "Drei Schafe in drei Nächten, zerrissen am Rand des Moores. Die Leute reden von einem Werwolf. Der Schmied hat Silbernägel geschmiedet, die Kinder schlafen bei Licht. Der Hirte schwört, er habe es gesehen: groß wie ein Kalb, mit Augen wie Glut.", "optionen": [{"text": "Mit dem Hirten zu den Kadavern gehen", "weiter": "kadaver"}, {"text": "Im Dorf fragen, wer zuletzt im Moor war", "weiter": "fragen"}, {"text": "Silbernägel einstecken und gleich los", "weiter": "weg", "folgen": {"flag": ["silber"]}}]}, "fragen": {"ort": "dorf", "text": "Niemand geht freiwillig ins Moor. Nur der alte Ebbo, der Torfstecher, der seit dem Tod seiner Frau draußen in einer Hütte lebt. „Der redet mit Hunden“, sagt jemand. „Und mit Toten.“ Und dann: Vor einem Monat hat der Rat Ebbo das Torfrecht entzogen. Weil er nicht mehr zahlen konnte.", "optionen": [{"text": "Zu Ebbos Hütte gehen", "weiter": "weg", "folgen": {"flag": ["ebbo_verdacht"]}}, {"text": "Erst die Kadaver ansehen", "weiter": "kadaver"}]}, "kadaver": {"ort": "wald", "text": "Die Kadaver liegen im Schilf. Fliegen. Der Hirte hält sich die Nase zu. Du kniest dich hin und liest, was der Boden erzählt.", "minispiel": {"art": "spuren", "schwer": 2, "titel": "Spuren deuten", "erfolg": {"text": "Keine Klauen, keine riesigen Pfoten. Hundespuren – große, aber Hunde. Zwei. Und dazwischen der Abdruck eines Stiefels mit geflicktem Absatz.", "weiter": "weg", "folgen": {"flag": ["hundespur", "stiefel"]}}, "misserfolg": {"text": "Der Boden ist zertrampelt, du erkennst nichts Sicheres. Nur: Was immer es war, es war nicht allein.", "weiter": "weg"}}, "optionen": []}, "weg": {"ort": "wald", "text": "Das Moor beginnt, wo die Birken krumm werden. Der Boden schmatzt unter jedem Schritt. Nebel kriecht zwischen den Grasbulten hervor.", "reise": {"minuten": 45, "weiter": "hütte", "text": "Du gehst {mit} ins Nebelmoor.", "begegnung": {"chance": 0.4, "szenen": ["b_irrlicht"]}}}, "b_irrlicht": {"ort": "wald", "text": "Ein Licht schwebt über dem Wasser, flackernd, lockend. Der Hirte, falls er mitkam, würde jetzt beten. Es zieht dich in eine andere Richtung als den Pfad.", "optionen": [{"text": "Dem Licht nicht folgen und den festen Weg suchen", "tag": "[Spuren lesen]", "probe": {"id": "spuren", "dc": 11}, "erfolg": {"text": "Du hältst dich an die Birken. Das Licht verlischt, enttäuscht, so scheint es.", "weiter": "hütte"}, "misserfolg": {"text": "Ein Fehltritt, du versinkst bis zur Hüfte. Mühsam ziehst du dich heraus, durchnässt und frierend.", "weiter": "hütte", "folgen": {"flag": ["nass"]}}}]}, "hütte": {"ort": "wald", "text": "Ebbos Hütte steht auf Pfählen. Davor zwei Hunde, groß, mager, mit verfilztem Fell – Wolfshunde. Sie knurren nicht. Sie warten. In der Tür steht Ebbo, ein Beil in der Hand. „Ich weiß, warum du kommst. Sie sind’s nicht gewesen.“", "optionen": [{"text": "„Die Spuren sagen etwas anderes.“", "wenn": {"flag": "hundespur"}, "weiter": "ebbo_streit"}, {"text": "Seine Augen lesen: lügt er?", "tag": "[Menschenkenntnis]", "probe": {"id": "menschenkenntnis", "dc": 12}, "erfolg": {"text": "Er lügt nicht – nicht ganz. Er glaubt, was er sagt. Aber er verschweigt etwas. Er hat Angst, und nicht vor dir.", "weiter": "ebbo_angst"}, "misserfolg": {"text": "Sein Gesicht ist wie Torf: braun, rissig, unlesbar.", "weiter": "ebbo_streit"}}, {"text": "Ohne Warnung angreifen, bevor die Hunde es tun", "tag": "[Kampf]", "weiter": "kampf_hunde"}]}, "ebbo_streit": {"ort": "wald", "text": "„Die Spuren!“ Ebbo lacht heiser. „Meine Hunde waren hier, angebunden, jede Nacht. Aber ihr glaubt ja lieber an Werwölfe – oder an den Alten, dem ihr das Torfrecht genommen habt.“ Die Hunde stellen die Nackenhaare auf.", "optionen": [{"text": "Ruhig bleiben und die Hunde besänftigen", "tag": "[Beruhigen]", "probe": {"id": "beruhigen", "dc": 13}, "erfolg": {"text": "Du gehst in die Hocke, redest leise. Der größere Hund schnüffelt an deiner Hand. Ebbo senkt das Beil. „Na gut. Komm rein.“", "weiter": "ebbo_angst"}, "misserfolg": {"text": "Ein Hund springt. Ebbo schreit etwas – zu spät.", "weiter": "kampf_hunde"}}, {"text": "„Zeig mir deine Stiefel.“", "wenn": {"flag": "stiefel"}, "weiter": "stiefel"}]}, "stiefel": {"ort": "wald", "text": "Ebbo zögert, dann hebt er einen Fuß. Der Absatz ist heil. „Zufrieden?“ Aber an der Wand hängt ein zweites Paar. Mit geflicktem Absatz. Zu klein für Ebbo.", "optionen": [{"text": "„Wem gehören die?“", "weiter": "ebbo_angst"}]}, "ebbo_angst": {"ort": "wald", "text": "Drinnen riecht es nach Rauch und nassem Hund. Ebbo setzt sich schwer. „Mein Enkel. Jannik. Kam vor zwei Monaten aus Rabenfels, desertiert. Wenn sie ihn finden, hängen sie ihn. Er hat Hunger. Er hat die Hunde nachts mitgenommen. Ich hab’s zu spät gemerkt.“ Er sieht dich an. „Er ist da draußen. Er kommt heute Nacht wieder.“", "optionen": [{"text": "„Dann warten wir auf ihn. Zusammen.“", "weiter": "nacht"}, {"text": "„Das muss das Dorf erfahren.“", "weiter": "ende_verrat", "ergebnis": "Ebbo sagt nichts mehr. Er sieht nur zu, wie du gehst."}]}, "nacht": {"ort": "wald", "text": "Die Nacht kommt schnell im Moor. Du liegst mit Ebbo im Schilf. Gegen Mitternacht: Hecheln, Schritte. Ein junger Mann, abgemagert, mit einem Messer, die Hunde an der Leine. Aber nicht nur er. Hinter ihm, im Nebel, Fackeln. Drei Reiter in Grau. Häscher aus Rabenfels.", "optionen": [{"text": "Jannik warnen und die Häscher aufhalten", "tag": "[Kampf]", "weiter": "kampf_haescher"}, {"text": "Die Häscher mit einer Lüge auf eine falsche Fährte schicken", "tag": "[Überreden]", "probe": {"id": "ueberreden", "dc": 14}, "erfolg": {"text": "„Der Deserteur? Richtung Furt, vor einer Stunde.“ Der Anführer mustert dich, dann reißt er sein Pferd herum. Jannik zittert im Schilf.", "weiter": "jannik"}, "misserfolg": {"text": "„Du lügst.“ Der Anführer zieht das Schwert. „Und wer lügt, versteckt etwas.“", "weiter": "kampf_haescher"}}, {"text": "Still bleiben. Die Häscher tun lassen, was sie tun.", "weiter": "ende_haescher"}]}, "kampf_hunde": {"ort": "wald", "text": "Die Wolfshunde greifen an, schnell und lautlos.", "gefahr": true, "minispiel": {"art": "kampf", "schwer": 1, "titel": "Die Hunde im Moor", "gegner": "tiere", "dauer": 240, "kampfort": "wald", "erfolg": {"text": "Die Hunde liegen still. Ebbo kniet weinend neben ihnen. „Sie waren alles, was ich hatte.“ Später findest du heraus, wer sie nachts mitgenommen hat. Aber das bringt keinen Hund zurück.", "weiter": "ende_hunde"}, "misserfolg": {"text": "Du fliehst blutend aus dem Moor.", "weiter": "ende_flucht", "folgen": {"gefahr": 1}}}, "optionen": []}, "kampf_haescher": {"ort": "wald", "text": "Fackeln, Pferde, Stahl. Ebbos Hunde stürzen sich auf die Pferde, Jannik schreit.", "gefahr": true, "minispiel": {"art": "kampf", "schwer": 2, "titel": "Häscher aus Rabenfels", "gegner": "banditen", "dauer": 360, "kampfort": "wald", "erfolg": {"text": "Die Häscher fliehen, einer ist verwundet. Sie werden wiederkommen – oder melden, dass im Hügelland jemand Deserteure schützt.", "weiter": "jannik", "folgen": {"flag": ["haescher_geschlagen"]}}, "misserfolg": {"text": "Jannik wird gepackt und aufs Pferd geworfen. Ebbo schreit seinen Namen in den Nebel.", "weiter": "ende_haescher", "folgen": {"gefahr": 1}}}, "optionen": []}, "jannik": {"ort": "wald", "text": "Jannik sitzt in Ebbos Hütte, eingehüllt in eine Decke. „Ich wollte nicht stehlen. Aber ich konnte nicht ins Dorf. Jeder hätte gefragt, wer ich bin.“ Ebbo hält seine Hand. Die Schafe, die zerrissenen Schafe – jemand muss dafür geradestehen.", "optionen": [{"text": "„Komm mit ins Dorf. Erzähl es selbst. Ich stehe neben dir.“", "weiter": "ende_beichte"}, {"text": "Die Schafe selbst bezahlen und schweigen", "weiter": "ende_schweigen", "folgen": {"holz": -30}}, {"text": "Jannik helfen, weiter nach Süden zu fliehen", "weiter": "ende_flucht_jannik"}]}, "ende_beichte": {"ort": "dorf", "text": "Der Rat hört Jannik an. Es gibt Geschrei, dann Schweigen, dann einen Vorschlag: Er hütet den Winter über die Schafe, um sie abzuarbeiten. Ebbo bekommt sein Torfrecht zurück – auf Bewährung. Der Werwolf ist tot. Ein Junge lebt.", "ende": true, "folgen": {"chronik": ["moor_beichte", "Ich habe Jannik vor den Rat gebracht – nicht als Gefangenen, sondern als jemanden, der etwas zu sagen hat."], "beute": {"stufe": 2, "text": "Ebbo drückt dir etwas in die Hand, das seiner Frau gehörte:"}}}, "ende_schweigen": {"ort": "dorf", "text": "Du sagst dem Dorf, der Werwolf sei tot, und bezahlst die Schafe aus eigener Tasche. Die Kinder schlafen wieder ohne Licht. Nur du weißt, was im Moor lebt. Eine Lüge, die niemandem schadet. Hoffst du.", "ende": true, "folgen": {"chronik": ["moor_schweigen", "Ich habe für Jannik gelogen. Der Werwolf ist tot, sage ich. Es stimmt sogar."], "beute": {"stufe": 1}}}, "ende_flucht_jannik": {"ort": "dorf", "text": "Du bringst Jannik bis zur Straße nach Süden, gibst ihm Brot und einen Namen, den er benutzen kann. Ebbo bleibt allein im Moor. Er winkt dir nicht nach, als du zurückkommst. Aber er nickt.", "ende": true, "folgen": {"chronik": ["moor_flucht", "Ich habe einem Deserteur zur Flucht verholfen. Rabenfels würde mich dafür hängen."]}}, "ende_haescher": {"ort": "dorf", "text": "Die Häscher reiten mit Jannik davon. In Rabenfels hängen sie Deserteure am Tor. Ebbo kommt nicht mehr ins Dorf, nie mehr. Die Schafe werden nicht mehr gerissen. Das Dorf nennt dich den, der den Werwolf vertrieben hat.", "ende": true, "folgen": {"chronik": ["moor_haescher", "Ich habe zugesehen, wie sie Jannik mitnahmen. Das Dorf feiert mich dafür."]}}, "ende_verrat": {"ort": "dorf", "text": "Der Rat schickt Männer ins Moor. Jannik flieht, die Hunde werden erschlagen, Ebbo verliert seine Hütte. Das Dorf ist sicher. Es hat dich nur ein Stück von dir selbst gekostet.", "ende": true, "folgen": {"chronik": ["moor_verrat", "Ich habe Ebbo verraten. Es war das Richtige für das Dorf. Glaube ich."]}}, "ende_hunde": {"ort": "dorf", "text": "Du kommst mit zwei Hundefellen zurück. Das Dorf jubelt: der Werwolf ist tot. Ebbo kommt nie wieder ins Dorf. Erst Wochen später erfährst du von dem Jungen, den er versteckte.", "ende": true, "folgen": {"chronik": ["moor_hunde", "Ich habe Ebbos Hunde getötet. Sie waren nicht das Ungeheuer."]}}, "ende_flucht": {"ort": "dorf", "text": "Mit zerbissenem Arm kommst du zurück. Das Moor behält seine Geheimnisse.", "ende": true, "folgen": {"chronik": ["moor_flucht_selbst", "Das Moor hat mich zurückgeschickt."]}}}}}, {"id": "g_siegel", "titel": "Das Siegel der Witwe", "kurz": "Zwei Testamente, ein Siegel, und eine Tote, die Rätsel liebte. Der Rat bittet dich, die Wahrheit zu finden.", "schwer": 1, "fundort": null, "def": {"start": "start", "szenen": {"start": {"ort": "dorf", "text": "Die alte Gesine ist gestorben, reich für Dorfverhältnisse: ein Hof, zwei Kühe, ein Silberbecher. Jetzt liegen zwei Testamente auf dem Tisch des Rats. Eins vermacht alles ihrer Nichte Marlene, die sie gepflegt hat. Das andere ihrem Neffen Kaspar, der in der Stadt lebt. Beide tragen Gesines Siegel. Der Rat bittet dich, die Wahrheit zu finden.", "optionen": [{"text": "Die Testamente genau untersuchen", "weiter": "papiere"}, {"text": "Mit Marlene sprechen", "weiter": "marlene"}, {"text": "Mit Kaspar sprechen", "weiter": "kaspar"}]}, "papiere": {"ort": "dorf", "text": "Zwei Pergamente. Marlenes Testament ist fleckig, die Schrift zittrig, datiert auf den Herbst. Kaspars ist sauber, mit fester Hand geschrieben, datiert auf den Winter – also später. Das Siegel: ein Ährenkranz. Bei Kaspars Testament ist das Wachs dunkler.", "optionen": [{"text": "Das Siegel vergleichen", "tag": "[Altes Wissen]", "probe": {"id": "altes_wissen", "dc": 12}, "erfolg": {"text": "In Marlenes Siegel ist ein winziger Riss im Ährenkranz – eine Kerbe im Siegelring. Kaspars Siegel ist makellos. Entweder wurde der Ring repariert … oder es ist ein anderer Ring.", "weiter": "papiere2", "folgen": {"flag": ["kerbe"]}}, "misserfolg": {"text": "Für dich sehen beide Siegel gleich aus.", "weiter": "papiere2"}}, {"text": "Die Schrift vergleichen", "weiter": "papiere2", "ergebnis": "Gesines Hände zitterten im letzten Jahr, das weiß jeder. Kaspars Testament ist mit ruhiger Hand geschrieben. Hat sie es diktiert? Wem?", "folgen": {"flag": ["schrift"]}}]}, "papiere2": {"ort": "dorf", "text": "Wo ist Gesines Siegelring jetzt? Der Rat weiß es nicht. Im Nachlass war er nicht.", "optionen": [{"text": "Marlene befragen", "weiter": "marlene"}, {"text": "Kaspar befragen", "weiter": "kaspar"}, {"text": "Gesines Hof durchsuchen", "weiter": "hof"}]}, "marlene": {"ort": "dorf", "text": "Marlene ist rotäugig und müde. „Drei Jahre hab ich sie gewaschen, gefüttert, ihr vorgelesen. Kaspar kam zweimal. Zur Kirmes.“ Sie verschränkt die Arme. „Ja, ich will den Hof. Ich hab ihn verdient.“", "optionen": [{"text": "Fragen, wo der Siegelring ist", "tag": "[Menschenkenntnis]", "probe": {"id": "menschenkenntnis", "dc": 11}, "erfolg": {"text": "Sie zögert eine Sekunde zu lange. „Weiß ich nicht.“ Sie weiß es.", "weiter": "marlene2", "folgen": {"flag": ["marlene_luegt"]}}, "misserfolg": {"text": "„Keine Ahnung. Tante Gesine trug ihn immer.“", "weiter": "marlene2"}}, {"text": "„Hat Gesine dir je gesagt, was sie wollte?“", "weiter": "marlene2", "ergebnis": "„Sie hat gesagt, Kaspar soll den Becher kriegen. Weil er ihn als Kind so mochte. Sonst nichts.“", "folgen": {"flag": ["becher"]}}]}, "marlene2": {"ort": "dorf", "text": "Marlene steht auf. „Ich muss die Kühe melken. Meine Kühe.“", "optionen": [{"text": "Kaspar befragen", "wenn": {"nicht_flag": "kaspar_besucht"}, "weiter": "kaspar"}, {"text": "Gesines Hof durchsuchen", "weiter": "hof"}, {"text": "Zum Rat gehen und entscheiden", "weiter": "rat"}]}, "kaspar": {"ort": "dorf", "text": "Kaspar trägt Stadtkleider und ein freundliches Lächeln. „Tante Gesine hat mir im Winter geschrieben. Sie hatte Angst, dass Marlene sie bestiehlt. Ich bin sofort gekommen, und sie hat mir das Testament diktiert. Dem Schreiber Ulf aus Furtenau.“", "optionen": [{"text": "Seine Geschichte prüfen: Wann genau war er da?", "tag": "[Menschenkenntnis]", "probe": {"id": "menschenkenntnis", "dc": 13}, "erfolg": {"text": "„Im Januar“, sagt er. Aber im Januar war der Pass zugeschneit, drei Wochen lang. Das weißt du. Er weiß es offenbar nicht.", "weiter": "kaspar2", "folgen": {"flag": ["januar"]}}, "misserfolg": {"text": "Seine Geschichte klingt glatt. Zu glatt? Oder einfach wahr?", "weiter": "kaspar2"}}, {"text": "„Darf ich den Brief sehen, den sie dir schrieb?“", "weiter": "kaspar2", "ergebnis": "„Verbrannt. Sie bat mich darum.“ Natürlich.", "folgen": {"flag": ["kaspar_besucht"]}}]}, "kaspar2": {"ort": "dorf", "text": "Kaspar lächelt weiter. „Ich will Marlene nichts Böses. Sie kann bleiben, als Magd.“", "optionen": [{"text": "Gesines Hof durchsuchen", "weiter": "hof"}, {"text": "Marlene befragen", "wenn": {"nicht_flag": "marlene_luegt"}, "weiter": "marlene"}, {"text": "Zum Rat gehen und entscheiden", "weiter": "rat"}]}, "hof": {"ort": "dorf", "text": "Gesines Kammer. Ein Bett, eine Truhe mit Schloss, ein Spinnrad. Unter dem Bett eine lose Diele.", "minispiel": {"art": "schloss", "schwer": 2, "titel": "Die Truhe öffnen", "erfolg": {"text": "Klick. In der Truhe: Wäsche, ein Gebetbuch – und darin eingelegt ein Zettel mit Gesines zittriger Schrift.", "weiter": "zettel", "folgen": {"flag": ["zettel"]}}, "misserfolg": {"text": "Das Schloss gibt nicht nach. Aber unter der Diele findest du etwas.", "weiter": "diele"}}, "optionen": []}, "zettel": {"ort": "dorf", "text": "Auf dem Zettel steht ein Vers – Gesine liebte Rätsel, das wusste jeder. Darunter: „Wer dies löst, weiß, wo mein Wille ruht.“", "raetsel": {"frage": "Ich trag dein Zeichen, doch schreib ich nie; ich mach dich wahr und lüge nie. Wer mich verliert, verliert den Mund, mit dem er spricht zur letzten Stund. Was bin ich?", "antworten": ["siegel", "siegelring", "ring", "der siegelring", "das siegel", "mein siegel"], "hinweise": ["Es hat mit Wachs zu tun.", "Gesine trug ihn am Finger."], "versuche": 3, "erfolg": {"text": "Der Siegelring. Und dann siehst du es: Am Spinnrad, in der Spindel versteckt, steckt ein Ring mit einem Ährenkranz – und einer Kerbe.", "weiter": "ring", "folgen": {"flag": ["ring"]}}, "misserfolg": {"text": "Du kommst nicht drauf. Aber unter der Diele ist noch etwas.", "weiter": "diele"}}, "optionen": []}, "diele": {"ort": "dorf", "text": "Unter der Diele: ein kleiner Lederbeutel. Darin drei Silbermünzen mit dem Stempel der Stadtmünze – und eine Quittung über einen Siegelring, gefertigt von einem Goldschmied in Furtenau. Bestellt im Dezember. Auf den Namen Kaspar.", "optionen": [{"text": "Damit zum Rat", "weiter": "rat", "folgen": {"flag": ["quittung"]}}]}, "ring": {"ort": "dorf", "text": "Der echte Ring hat die Kerbe. Also ist Marlenes Testament mit dem echten Ring gesiegelt – und Kaspars mit einem nachgemachten. Aber warum hat Marlene gezögert, als du nach dem Ring fragtest? Weil sie wusste, wo er war. Hat sie ihn versteckt, damit niemand ein neues Testament siegeln kann? Oder hat Gesine ihn selbst versteckt?", "optionen": [{"text": "Zum Rat, mit allem, was du weißt", "weiter": "rat"}]}, "rat": {"ort": "dorf", "text": "Der Rat sitzt um den Tisch. Marlene auf der einen Seite, Kaspar auf der anderen. Alle sehen dich an.", "optionen": [{"text": "„Kaspars Testament ist gefälscht. Der Ring beweist es.“", "wenn": {"flag": "ring"}, "weiter": "ende_beweis"}, {"text": "„Kaspar hat sich einen Ring machen lassen. Hier ist die Quittung.“", "wenn": {"flag": "quittung"}, "weiter": "ende_beweis"}, {"text": "„Kaspar war im Januar gar nicht hier. Der Pass war zu.“", "tag": "[Überreden]", "probe": {"id": "ueberreden", "dc": 12}, "erfolg": {"text": "Kaspar wird blass. Dann rot. Dann gesteht er nicht – aber er zieht sein Testament zurück. „Ich will keinen Streit in der Familie.“", "weiter": "ende_rueckzug"}, "misserfolg": {"text": "„Ich kam über die Furt“, sagt Kaspar ruhig. Der Rat zuckt mit den Schultern. Zweifel bleibt.", "weiter": "ende_teilung"}, "wenn": {"flag": "januar"}}, {"text": "„Ich kann nichts beweisen. Teilt den Hof.“", "weiter": "ende_teilung"}, {"text": "„Marlene hat den Ring versteckt. Auch sie hat gelogen.“", "wenn": {"flag": "marlene_luegt"}, "weiter": "ende_beide"}]}, "ende_beweis": {"ort": "dorf", "text": "Kaspar wird aus dem Dorf gewiesen, seine Fälschung vor allen verbrannt. Marlene bekommt den Hof. Als alle gegangen sind, kommt sie zu dir. „Ich hab den Ring versteckt“, sagt sie. „Damit er genau das nicht tun kann. Gesine hat es gewusst.“ Sie gibt dir den Silberbecher. „Den hätte sie dir gegönnt.“", "ende": true, "folgen": {"chronik": ["siegel_beweis", "Ich habe Kaspars Fälschung aufgedeckt. Marlene hat den Hof – und mir einen Becher geschenkt."], "beute": {"stufe": 2, "text": "Marlene drückt dir den Silberbecher in die Hand – und noch etwas aus Gesines Truhe:"}}}, "ende_rueckzug": {"ort": "dorf", "text": "Kaspar reist ab, ohne sich zu verabschieden. Marlene bekommt den Hof. Ob er ein Betrüger war oder nur ein Mann, der sich in eine schlechte Idee verrannt hat, wirst du nie ganz wissen.", "ende": true, "folgen": {"chronik": ["siegel_rueckzug", "Kaspar hat sein Testament zurückgezogen. Ohne Beweis, aber mit genug Zweifel."], "beute": {"stufe": 1}}}, "ende_teilung": {"ort": "dorf", "text": "Der Rat teilt: Marlene den Hof, Kaspar die Kühe und den Becher. Beide sind unzufrieden. Das, sagt der Älteste, ist meistens ein Zeichen, dass es gerecht war. Du bist dir da nicht so sicher.", "ende": true, "folgen": {"chronik": ["siegel_teilung", "Gesines Erbe wurde geteilt. Niemand ist zufrieden. Vielleicht war das gerecht."]}}, "ende_beide": {"ort": "dorf", "text": "Der Rat ist empört – über beide. Marlene muss sich erklären. Sie tut es, mit Tränen: Sie habe den Ring versteckt, weil sie Kaspar nicht traute. Am Ende bekommt sie den Hof, aber das Dorf sieht sie anders an. Wahrheit hat ihren Preis, auch wenn sie richtig ist.", "ende": true, "folgen": {"chronik": ["siegel_beide", "Ich habe beide Lügen aufgedeckt. Die Wahrheit war richtig – und sie hat trotzdem jemandem wehgetan."], "beute": {"stufe": 1}}}}}}, {"id": "g_krankheit", "titel": "Die stille Krankheit", "kurz": "Eine Familie siecht dahin, sonst niemand. Das Dorf flüstert von einem Fluch – und hat schon jemanden im Verdacht.", "schwer": 1, "fundort": null, "def": {"start": "start", "szenen": {"start": {"ort": "dorf", "text": "Im Haus des Böttchers Harm sind alle krank: Harm, seine Frau, die drei Kinder. Bauchkrämpfe, Zittern, graue Haut. Seit dem Frühjahr wird es schlimmer. Sonst ist im Dorf niemand krank. Die Leute bekreuzigen sich, wenn sie vorbeigehen. „Ein Fluch“, flüstern sie. „Harm hat sich mit der Kräuterfrau gestritten.“", "optionen": [{"text": "Das Haus der Familie untersuchen", "weiter": "haus"}, {"text": "Mit der Kräuterfrau sprechen", "weiter": "kraeuterfrau"}, {"text": "Die Kranken selbst untersuchen", "weiter": "kranke"}]}, "kranke": {"ort": "dorf", "text": "Die Jüngste liegt auf dem Strohsack, ihr Zahnfleisch hat einen bläulichen Saum. Harm kann kaum die Hand heben. „Wir essen, was alle essen“, flüstert er. „Wir trinken aus dem Brunnen wie alle.“", "optionen": [{"text": "Die Anzeichen deuten", "tag": "[Heilkunde]", "probe": {"id": "heilkunde", "dc": 13}, "erfolg": {"text": "Der blaue Saum am Zahnfleisch, das Zittern – kein Fieber, keine Seuche. So etwas hast du einmal bei einem Bergmann gesehen. Gift. Langsames Gift, das sich im Körper sammelt.", "weiter": "haus", "folgen": {"flag": ["gift_erkannt"]}}, "misserfolg": {"text": "Das ist keine Krankheit, die du kennst. Aber Fluch? Daran glaubst du nicht.", "weiter": "haus"}}]}, "haus": {"ort": "dorf", "text": "Das Haus ist sauber, ärmlich. Fässer in jeder Ecke – Harm ist Böttcher. In der Küche glänzt ein neuer Kessel, kupferrot, im Frühjahr gekauft von einem fahrenden Händler. Daneben Krüge mit Apfelmost, ein Topf mit sauren Bohnen.", "optionen": [{"text": "Den Kessel genauer ansehen", "weiter": "kessel"}, {"text": "Die Fässer untersuchen", "weiter": "faesser"}, {"text": "Den Most probieren", "weiter": "most", "ergebnis": "Süß, sehr süß. Harm sagt, sie trinken ihn seit dem Frühjahr jeden Abend – das letzte Fass vom Vorjahr, gesüßt nach einem alten Rezept seiner Großmutter."}]}, "kessel": {"ort": "dorf", "text": "Der Kessel ist innen verzinnt – schlecht. An mehreren Stellen glänzt grauweißes Metall durch. Der Händler hat behauptet, es sei Zinn. Ist es das?", "optionen": [{"text": "Das Metall erkennen", "tag": "[Altes Wissen]", "probe": {"id": "altes_wissen", "dc": 13}, "erfolg": {"text": "Es ist kein reines Zinn. Es ist weich, lässt sich mit dem Fingernagel ritzen – Blei. Wer darin Saures kocht, kocht Gift.", "weiter": "spur", "folgen": {"flag": ["blei_kessel"]}}, "misserfolg": {"text": "Du bist dir nicht sicher. Metall ist Metall.", "weiter": "spur"}}]}, "faesser": {"ort": "dorf", "text": "Die Fässer sind gut gemacht, Harm versteht sein Handwerk. Eins steht abseits: das Mostfass. An der Innenseite eine graue Kruste. „Großmutters Rezept“, sagt Harms Frau schwach. „Bleizucker. Macht den Most süß und haltbar.“", "optionen": [{"text": "„Bleizucker?!“", "weiter": "spur", "ergebnis": "Sie weiß nicht, was sie sagt. Für sie ist es Zucker. Für dich ist es die Antwort – oder ein Teil davon.", "folgen": {"flag": ["bleizucker"]}}]}, "most": {"ort": "dorf", "text": "Der süße Nachgeschmack bleibt lange auf der Zunge. Ein bisschen metallisch.", "optionen": [{"text": "Die Fässer untersuchen", "weiter": "faesser"}, {"text": "Den Kessel ansehen", "weiter": "kessel"}]}, "kraeuterfrau": {"ort": "dorf", "text": "Die Kräuterfrau wohnt am Waldrand. Sie lacht freudlos, als du von Fluch sprichst. „Harm hat mir im Winter Fässer versprochen und nicht geliefert. Ich hab ihn verflucht, ja. Mit Worten. Wenn Worte töten könnten, wäre das halbe Dorf tot.“ Sie wird ernst. „Aber was die haben, ist kein Fluch. Bring mir eine Probe von dem, was sie essen.“", "optionen": [{"text": "Zurück zum Haus, Proben holen", "weiter": "haus", "folgen": {"flag": ["kf_hilft"]}}, {"text": "„Sie geben dir die Schuld. Wenn du hilfst, hört das auf.“", "tag": "[Überreden]", "probe": {"id": "ueberreden", "dc": 10}, "erfolg": {"text": "Sie seufzt. „Na gut. Ich komme mit.“", "weiter": "haus", "folgen": {"flag": ["kf_hilft", "kf_dabei"]}}, "misserfolg": {"text": "„Das hört nie auf“, sagt sie. „Aber bring mir die Probe.“", "weiter": "haus", "folgen": {"flag": ["kf_hilft"]}}}]}, "spur": {"ort": "dorf", "text": "Du hast genug gesehen, um zu wissen: Das Gift kommt aus diesem Haus. Die Frage ist nur noch, was du damit machst – und wem du es sagst. Draußen hat sich eine Menge gesammelt. Jemand hat eine Fackel. „Verbrennt die Hexe!“, ruft einer. Sie meinen die Kräuterfrau.", "optionen": [{"text": "Vor die Menge treten und erklären", "weiter": "menge"}, {"text": "Erst die Familie behandeln, dann die Menge", "weiter": "behandeln"}]}, "behandeln": {"ort": "dorf", "text": "Die Familie muss sofort aufhören, Most zu trinken und aus dem Kessel zu essen. Aber das Gift ist schon in ihnen. Die Kräuterfrau kennt ein Mittel – wenn sie hier wäre. Sonst bleibt nur, was du selbst weißt.", "minispiel": {"art": "kraeuter", "schwer": 2, "titel": "Ein Gegenmittel mischen", "erfolg": {"text": "Milch, Eiweiß, ein Sud aus Brennnessel – es wird Wochen dauern, aber das Zittern lässt schon nach einer Stunde nach. Sie werden leben.", "weiter": "menge", "folgen": {"flag": ["geheilt"]}}, "misserfolg": {"text": "Du tust, was du kannst. Ob es reicht, weiß niemand.", "weiter": "menge"}}, "optionen": []}, "menge": {"ort": "dorf", "text": "Die Menge vor dem Haus. Fackeln, Wut, Angst – vor allem Angst. Wenn es kein Fluch ist, ist es etwas, das jeden treffen kann. Das macht mehr Angst als eine Hexe.", "optionen": [{"text": "„Es ist Blei! Im Most und im Kessel! Die Kräuterfrau hat nichts getan!“", "tag": "[Überreden]", "probe": {"id": "ueberreden", "dc": 13}, "erfolg": {"text": "Erst Stille. Dann fragt jemand: „Blei? Meine Großmutter hat auch Bleizucker benutzt.“ Plötzlich rennen die Leute nach Hause, zu ihren eigenen Mostfässern. Die Fackeln sind vergessen.", "weiter": "ende_wahrheit"}, "misserfolg": {"text": "„Ausreden! Die Hexe hat ihn bezahlt!“ Die Menge drängt vorwärts.", "weiter": "ende_angst"}, "wenn": {"flag": "bleizucker"}}, {"text": "„Der Kessel des Händlers ist vergiftet! Wer hat noch einen gekauft?“", "tag": "[Überreden]", "probe": {"id": "ueberreden", "dc": 12}, "erfolg": {"text": "Drei Hände gehen hoch. Gemurmel, dann Panik – aber die richtige Art von Panik. Die Kessel werden in den Bach geworfen.", "weiter": "ende_wahrheit"}, "misserfolg": {"text": "Niemand glaubt dir. Ein Kessel? Lächerlich.", "weiter": "ende_angst"}, "wenn": {"flag": "blei_kessel"}}, {"text": "Die Menge beruhigen, ohne Beweis", "tag": "[Beruhigen]", "probe": {"id": "beruhigen", "dc": 15}, "erfolg": {"text": "Deine Ruhe steckt an. Einer nach dem anderen senkt die Fackel. „Morgen“, sagt jemand. „Morgen reden wir weiter.“", "weiter": "ende_aufschub"}, "misserfolg": {"text": "Es nützt nichts.", "weiter": "ende_angst"}}]}, "ende_wahrheit": {"ort": "dorf", "text": "In drei weiteren Häusern findet man Bleizucker, in zweien einen der Kessel. Niemand sonst war schon so krank wie Harms Familie – noch nicht. Die Kräuterfrau bekommt keine Entschuldigung. Aber am nächsten Markttag kaufen die Leute wieder bei ihr. Das ist im Dorf dasselbe.", "ende": true, "folgen": {"chronik": ["krankheit_wahrheit", "Ich habe das Gift in Harms Haus gefunden. Kein Fluch – Blei. Das Dorf hat seine Fackeln gelöscht."], "beute": {"stufe": 2, "text": "Harm, noch zitternd, gibt dir das Beste, was er hat:"}}}, "ende_aufschub": {"ort": "dorf", "text": "Die Nacht vergeht ohne Feuer. Am Morgen ist die Wut verraucht, aber der Verdacht bleibt an der Kräuterfrau kleben. Harms Familie erholt sich langsam, seit sie keinen Most mehr trinken – ein Zufall, sagen die Leute.", "ende": true, "folgen": {"chronik": ["krankheit_aufschub", "Ich habe die Menge beruhigt, aber die Wahrheit kam nicht ans Licht."]}}, "ende_angst": {"ort": "dorf", "text": "Die Menge zieht zum Waldrand. Die Kräuterfrau ist geflohen, ihre Hütte brennt. Harms Familie erholt sich trotzdem, weil sie nach deinem Rat keinen Most mehr trinkt. Das Dorf glaubt, der Fluch sei mit dem Feuer gebrochen.", "ende": true, "folgen": {"chronik": ["krankheit_angst", "Sie haben die Hütte der Kräuterfrau verbrannt. Ich hatte die Wahrheit und konnte sie nicht hörbar machen."]}}}}}, {"id": "g_prediger", "titel": "Der Prediger von der Heide", "kurz": "Ein Wanderprediger hetzt gegen Fremde – und in manchem hat er recht. Heute will er zwei Familien vertreiben.", "schwer": 2, "fundort": null, "def": {"start": "start", "szenen": {"start": {"ort": "dorf", "text": "Seit drei Tagen predigt ein Wanderprediger auf dem Dorfplatz. Bruder Anshelm, hager, mit Augen, die brennen. „Fremde bringen Seuchen, Diebstahl und Unglauben!“ Und das Schlimme: Letzten Monat hat tatsächlich ein Fremder Hühner gestohlen. Die Menge wird jeden Abend größer. Heute verlangt Anshelm, dass die zwei Familien, die im Sommer aus Rabenfels gekommen sind, das Dorf verlassen.", "optionen": [{"text": "Zuhören, was er genau sagt", "weiter": "predigt"}, {"text": "Mit den Familien aus Rabenfels sprechen", "weiter": "familien"}, {"text": "Nach dem Prediger fragen: Wer ist er?", "weiter": "herkunft"}]}, "predigt": {"ort": "dorf", "text": "„Ich frage euch“, ruft Anshelm, „wer hat euer Korn gegessen im letzten Winter? Wer schläft in den Häusern, die eure Söhne bauen sollten? Ist es Hass, das eigene Haus zu schützen? Oder ist es Liebe?“ Die Leute nicken. Er sagt nicht nur Falsches. Das macht ihn gefährlich.", "optionen": [{"text": "Seine Rede durchschauen: Was will er wirklich?", "tag": "[Menschenkenntnis]", "probe": {"id": "menschenkenntnis", "dc": 12}, "erfolg": {"text": "Er glaubt, was er sagt – aber er braucht die Menge. Jedes Nicken nährt ihn. Er schaut immer wieder zu einem Mann am Rand: dem reichen Bauern Gottfried, der die Hälfte des Brachlands will, auf dem die Rabenfelser siedeln.", "weiter": "nach_predigt", "folgen": {"flag": ["gottfried"]}}, "misserfolg": {"text": "Er ist ein Fanatiker. Oder ein Heiliger. Schwer zu sagen bei Männern mit brennenden Augen.", "weiter": "nach_predigt"}}]}, "herkunft": {"ort": "dorf", "text": "Der Wirt weiß mehr. „Anshelm kam aus dem Kloster Morgenstern. Rausgeworfen, sagt man. Und seit er hier ist, sitzt er jeden Abend bei Gottfried am Tisch. Isst gut für einen Bettelmönch.“", "optionen": [{"text": "Zu den Familien gehen", "weiter": "familien", "folgen": {"flag": ["gottfried"]}}, {"text": "Die nächste Predigt anhören", "weiter": "predigt", "folgen": {"flag": ["gottfried"]}}]}, "familien": {"ort": "dorf", "text": "Die Rabenfelser wohnen in zwei Hütten auf dem Brachland, die sie selbst gebaut haben. Eine Frau, Agathe, flickt Netze. „Wir sind geflohen, weil der Graf unsere Männer in den Krieg holen wollte. Wir arbeiten. Wir zahlen. Wir haben niemandem etwas genommen.“ Ein Junge hinter ihr senkt den Kopf. Agathe merkt es nicht.", "optionen": [{"text": "Den Jungen beiseite nehmen", "weiter": "junge"}, {"text": "„Ich werde für euch sprechen.“", "weiter": "nach_predigt", "folgen": {"flag": ["versprochen"]}}]}, "junge": {"ort": "dorf", "text": "Der Junge heißt Mats, zwölf Jahre. Nach langem Schweigen platzt es aus ihm heraus: „Die Hühner. Das war ich. Meine kleine Schwester hatte Hunger. Ich wollte es zurückzahlen.“ Er weint. Wenn das herauskommt, hat Anshelm recht – irgendwie.", "optionen": [{"text": "„Wir sagen es gemeinsam. Vor allen.“", "weiter": "nach_predigt", "folgen": {"flag": ["mats_beichte"]}}, {"text": "„Das bleibt unter uns.“", "weiter": "nach_predigt", "folgen": {"flag": ["mats_geheim"]}}]}, "nach_predigt": {"ort": "dorf", "text": "Am Abend steht Anshelm wieder auf dem Brunnenrand. „Wer stellt sich mir entgegen?“, ruft er. Die Menge dreht sich um – zu dir.", "optionen": [{"text": "Öffentlich mit ihm streiten", "weiter": "disput1"}, {"text": "Ihn nach der Predigt allein aufsuchen", "weiter": "allein"}, {"text": "Gottfrieds Spiel aufdecken", "wenn": {"flag": "gottfried"}, "weiter": "gottfried_aufdecken"}]}, "disput1": {"ort": "dorf", "text": "„Du sprichst von Liebe zum eigenen Haus“, sagst du. Anshelm lächelt. „Und du? Liebst du die Fremden mehr als deine Nachbarn? Würdest du dein Brot einem Rabenfelser geben, wenn dein Kind hungert?“ Eine Falle. Jedes Ja macht dich zum Verräter, jedes Nein zu seinem Gefolgsmann.", "optionen": [{"text": "„Wenn mein Kind hungert, frage ich nicht, woher der kommt, der mit mir teilt.“", "tag": "[Überreden]", "probe": {"id": "ueberreden", "dc": 13}, "erfolg": {"text": "Ein Raunen. Eine Frau ruft: „Agathe hat mir im Winter Fisch gebracht!“ Anshelm verzieht das Gesicht. Der erste Riss.", "weiter": "disput2", "folgen": {"flag": ["riss"]}}, "misserfolg": {"text": "„Schöne Worte“, höhnt Anshelm. „Satte Worte.“ Gelächter.", "weiter": "disput2"}}, {"text": "„Du stellst falsche Fragen. Die Wahl ist nicht zwischen Nachbar und Fremdem. Sondern zwischen Angst und Arbeit.“", "tag": "[Altes Wissen]", "probe": {"id": "altes_wissen", "dc": 14}, "erfolg": {"text": "Die Leute denken nach. Anshelm merkt, dass Denken sein Feind ist. Er wird lauter.", "weiter": "disput2", "folgen": {"flag": ["riss"]}}, "misserfolg": {"text": "Zu abstrakt. Die Menge will einfache Antworten. Anshelm hat sie.", "weiter": "disput2"}}]}, "disput2": {"ort": "dorf", "text": "Anshelm hebt die Arme. „Dann sag ihnen die Wahrheit! Wer hat die Hühner gestohlen?“ Er weiß es. Irgendwie weiß er es. Mats steht in der Menge, weiß wie eine Wand.", "optionen": [{"text": "Mit Mats nach vorn treten und es selbst sagen lassen", "wenn": {"flag": "mats_beichte"}, "weiter": "ende_beichte"}, {"text": "„Ein hungriges Kind. Und was hat dein Gönner Gottfried gestohlen?“", "wenn": {"flag": "gottfried"}, "weiter": "gottfried_aufdecken"}, {"text": "Die Leute an ihre eigenen Hungerwinter erinnern", "tag": "[Beruhigen]", "probe": {"id": "beruhigen", "dc": 13}, "erfolg": {"text": "„Wer von euch hat nie aus Not etwas genommen?“ Stille. Lange. Dann geht der Erste. Und der Zweite. Anshelm bleibt allein auf dem Brunnenrand.", "weiter": "ende_leer"}, "misserfolg": {"text": "„Not ist keine Entschuldigung!“, brüllt jemand. Die Stimmung kippt.", "weiter": "ende_vertreibung"}}, {"text": "Schweigen", "weiter": "ende_vertreibung"}]}, "allein": {"ort": "dorf", "text": "Anshelm sitzt allein in der Kapelle, das Gesicht in den Händen. Ohne Menge ist er ein müder Mann. „Was willst du?“", "optionen": [{"text": "„Warum hat dich das Kloster rausgeworfen?“", "tag": "[Menschenkenntnis]", "probe": {"id": "menschenkenntnis", "dc": 12}, "erfolg": {"text": "Lange Stille. „Ich habe den Abt angeklagt. Er hat die Spenden der Armen für Wein ausgegeben. Niemand hat mir geglaubt. Niemand.“ Er sieht auf. „Jetzt hören sie mir zu.“", "weiter": "allein2", "folgen": {"flag": ["wunde"]}}, "misserfolg": {"text": "„Das geht dich nichts an.“", "weiter": "allein2"}}]}, "allein2": {"ort": "dorf", "text": "Anshelm steht auf. „Ich habe gesehen, was Menschen tun, wenn man ihnen vertraut. Lieber schütze ich sie vor Fremden als vor sich selbst.“", "optionen": [{"text": "„Du warst im Recht, und keiner hat dich gehört. Jetzt hast du unrecht, und alle hören zu. Willst du so jemand sein?“", "tag": "[Überreden]", "probe": {"id": "ueberreden", "dc": 14}, "erfolg": {"text": "Er zuckt, als hättest du ihn geschlagen. Dann setzt er sich wieder. „Was soll ich tun?“, fragt er leise. Am nächsten Morgen ist er fort. Auf dem Brunnen liegt ein Zettel: „Vergebt mir.“", "weiter": "ende_umkehr"}, "misserfolg": {"text": "„Geh“, sagt er. „Und komm morgen zur Predigt.“", "weiter": "nach_predigt2"}, "wenn": {"flag": "wunde"}}, {"text": "„Morgen werde ich dir widersprechen. Vor allen.“", "weiter": "nach_predigt2"}]}, "nach_predigt2": {"ort": "dorf", "text": "Der nächste Abend. Anshelm steht auf dem Brunnen. Er sieht dich an, bevor er beginnt.", "optionen": [{"text": "Öffentlich mit ihm streiten", "weiter": "disput1"}]}, "gottfried_aufdecken": {"ort": "dorf", "text": "„Wer profitiert, wenn die Rabenfelser gehen?“, fragst du laut. „Wer will das Brachland? Bei wem isst Bruder Anshelm jeden Abend?“ Alle Köpfe drehen sich zu Gottfried. Er läuft rot an. Anshelm starrt ihn an – er hat es nicht gewusst. Oder nicht wissen wollen.", "optionen": [{"text": "Gottfried vor dem Rat zur Rede stellen", "weiter": "ende_gottfried"}]}, "ende_beichte": {"ort": "dorf", "text": "Mats sagt es mit zitternder Stimme. Die Menge ist still. Dann tritt Agathe vor und verspricht, die Hühner zu ersetzen, doppelt. Anshelm öffnet den Mund – und schließt ihn wieder. Wer jetzt noch Fremde hasst, hasst ein weinendes Kind. Das bringen nicht viele fertig.", "ende": true, "folgen": {"chronik": ["prediger_beichte", "Mats hat gestanden, vor allen. Die Wahrheit hat Anshelm entwaffnet, nicht ich."], "beute": {"stufe": 1, "text": "Agathe bringt dir am nächsten Tag etwas aus Rabenfels:"}}}, "ende_leer": {"ort": "dorf", "text": "Am nächsten Morgen ist Anshelm weitergezogen, in ein anderes Dorf, zu anderen Ängsten. Die Rabenfelser bleiben. Das Brachland auch. Der Streit ist nicht gelöst, nur vertagt – wie fast alle Streite.", "ende": true, "folgen": {"chronik": ["prediger_leer", "Ich habe die Menge an ihre eigene Not erinnert. Anshelm ist weitergezogen."]}}, "ende_umkehr": {"ort": "dorf", "text": "Anshelm ist fort. Ob er zurück ins Kloster ging oder in ein anderes Dorf, um dort anders zu predigen, weiß niemand. Die Menge löst sich auf. Ein Mann wollte gehört werden. Am Ende hat ihm jemand zugehört.", "ende": true, "folgen": {"chronik": ["prediger_umkehr", "Ich habe Anshelm zugehört, als niemand es tat. Er hat aufgehört zu predigen."], "beute": {"stufe": 2, "text": "In der Kapelle hat er etwas für dich zurückgelassen:"}}}, "ende_gottfried": {"ort": "dorf", "text": "Der Rat entzieht Gottfried den Anspruch auf das Brachland. Anshelm verlässt das Dorf noch in derselben Nacht – beschämt, sagt man. Die Rabenfelser bleiben. Aber in Gottfrieds Haus brennt jetzt jede Nacht lange Licht. Er vergisst nicht.", "ende": true, "folgen": {"chronik": ["prediger_gottfried", "Ich habe aufgedeckt, wer hinter dem Prediger stand. Gottfried hat jetzt einen Feind: mich."], "beute": {"stufe": 1}}}, "ende_vertreibung": {"ort": "dorf", "text": "Die Rabenfelser packen noch in derselben Woche. Agathe sieht dich nicht an, als sie geht. Anshelm predigt noch einen Monat, dann zieht er weiter. Das Brachland bekommt Gottfried. Das Dorf ist ein bisschen ärmer geworden – nicht an Korn.", "ende": true, "folgen": {"chronik": ["prediger_vertreibung", "Die Rabenfelser mussten gehen. Ich habe es nicht verhindert."]}}}}}, {"id": "g_rutger", "titel": "Der Mann, der nicht schlafen will", "kurz": "Ein Heimkehrer aus dem Grenzkrieg hat sich mit einer Fackel eingeschlossen. Er sagt, die Toten kommen wieder.", "schwer": 2, "fundort": null, "def": {"start": "start", "szenen": {"start": {"ort": "dorf", "text": "Mitten in der Nacht wird an deine Tür gehämmert. Die Frau des Zimmermanns Rutger, im Nachthemd. „Er hat sich im Haus eingeschlossen. Mit einer Fackel. Er sagt, er brennt alles nieder, wenn jemand reinkommt. Er sagt, die Toten kommen wieder.“ Rutger war im Grenzkrieg. Seit er zurück ist, schläft er nicht.", "optionen": [{"text": "Sofort hingehen", "weiter": "haus"}, {"text": "Unterwegs fragen: Was ist im Krieg passiert?", "weiter": "frage"}]}, "frage": {"ort": "dorf", "text": "Sie redet schnell, atemlos. „Er redet nie davon. Nur einmal, betrunken: von einer Scheune bei Kammwacht. Dass er die Tür zugehalten hat. Mehr nicht.“ Sie weint. „Er ist ein guter Mann. Er war ein guter Mann.“", "optionen": [{"text": "Zum Haus", "weiter": "haus", "folgen": {"flag": ["scheune"]}}]}, "haus": {"ort": "dorf", "text": "Vor dem Haus stehen Nachbarn mit Eimern. Durch das Fenster sieht man Fackelschein. Rutgers Stimme: „Bleibt weg! Ich seh euch! Ich seh eure Gesichter!“ Einer der Nachbarn will die Tür eintreten.", "optionen": [{"text": "Den Nachbarn zurückhalten", "weiter": "tuer", "ergebnis": "„Wenn du die Tür eintrittst, zündet er das Haus an. Lass mich.“"}, {"text": "Die Tür eintreten lassen", "weiter": "ende_gewalt"}]}, "tuer": {"ort": "dorf", "text": "Du stehst vor der Tür. Drinnen atmet jemand schwer. „Wer da?“", "optionen": [{"text": "„Ich bin es, {held}. Ich will nur reden.“", "weiter": "reden1"}, {"text": "Leise durchs Fenster einsteigen, solange er abgelenkt ist", "tag": "[Flink]", "probe": {"id": "flink", "dc": 14}, "erfolg": {"text": "Du gleitest durch das Fenster in die Kammer. Rutger steht mit dem Rücken zu dir, die Fackel zitternd über einem Strohhaufen.", "weiter": "drinnen_heimlich"}, "misserfolg": {"text": "Ein Stuhl fällt um. Rutger fährt herum, die Fackel hoch. „Ihr seid gekommen!“", "weiter": "reden_panik"}}]}, "reden1": {"ort": "dorf", "text": "„Reden.“ Ein bitteres Lachen. „Die wollten auch reden. Damals. Die haben an die Tür geklopft und gerufen. Und ich hab sie zugehalten.“ Stille. „Hörst du sie auch?“", "optionen": [{"text": "„Ich höre nur dich, Rutger. Und deine Frau, die draußen weint.“", "tag": "[Beruhigen]", "probe": {"id": "beruhigen", "dc": 12}, "erfolg": {"text": "Ein langer Atemzug hinter der Tür. „Gerda?“ – „Sie ist hier.“ Das Zittern in seiner Stimme ändert sich. Weniger Angst. Mehr Schmerz.", "weiter": "reden2", "folgen": {"flag": ["ruhig1"]}}, "misserfolg": {"text": "„Lügner! Ihr seid alle Lügner!“ Etwas knistert. Rauch.", "weiter": "reden_panik"}}, {"text": "„Erzähl mir von der Scheune.“", "wenn": {"flag": "scheune"}, "weiter": "scheune"}]}, "reden_panik": {"ort": "dorf", "text": "Rauch quillt unter der Tür hervor. Rutger schreit, nicht vor Wut – vor Angst. „Ich hab’s nicht gewollt! Sie haben gesagt, die Scheune ist voller Feinde!“", "optionen": [{"text": "Ruhig und fest: „Rutger. Leg die Fackel in den Eimer neben dir. Jetzt.“", "tag": "[Beruhigen]", "probe": {"id": "beruhigen", "dc": 14}, "erfolg": {"text": "Zischen. Der Rauch wird weniger. Dann ein Schluchzen.", "weiter": "reden2", "folgen": {"flag": ["ruhig1"]}}, "misserfolg": {"text": "Er hört dich nicht mehr.", "weiter": "feuer"}}, {"text": "Die Tür eintreten und ihn rausziehen", "weiter": "feuer"}]}, "feuer": {"ort": "dorf", "text": "Flammen lecken am Stroh. Rutger kauert in der Ecke, die Arme über dem Kopf. Du musst ihn raus, bevor das Dach Feuer fängt.", "minispiel": {"art": "seil", "schwer": 2, "titel": "Durch den Rauch", "erfolg": {"text": "Du packst ihn am Kragen und schleifst ihn hinaus. Hinter euch löschen die Nachbarn. Das Haus steht noch. Rutger liegt im nassen Gras und starrt in den Himmel.", "weiter": "gras"}, "misserfolg": {"text": "Du schaffst es hinaus, aber verbrennst dir die Hände. Die Nachbarn retten das Haus. Rutger lebt.", "weiter": "gras", "folgen": {"gefahr": 1}}}, "optionen": []}, "drinnen_heimlich": {"ort": "dorf", "text": "Du stehst hinter ihm. Er murmelt Namen. Viele Namen. Er hat sie alle behalten.", "optionen": [{"text": "Ihm die Fackel aus der Hand nehmen", "weiter": "gras", "ergebnis": "Er wehrt sich nicht. Als hätte er darauf gewartet, dass jemand ihn aufhält."}, {"text": "„Rutger.“ Ganz leise seinen Namen sagen", "weiter": "reden2"}]}, "scheune": {"ort": "dorf", "text": "Lange Stille. Dann redet er, und es kommt wie Wasser durch einen Dammbruch. Der Hauptmann sagte, in der Scheune bei Kammwacht verstecken sich Feinde. Sie sollten die Tür zuhalten, während andere Feuer legten. Er hielt die Tür. Dann hörte er die Stimmen. Frauen. Kinder. Er hielt die Tür trotzdem. Weil der Hauptmann daneben stand.", "optionen": [{"text": "„Du hast einen Befehl befolgt. Die Schuld trägt der, der ihn gab.“", "tag": "[Überreden]", "probe": {"id": "ueberreden", "dc": 13}, "erfolg": {"text": "„Sag das den Kindern“, flüstert er. Aber die Fackel sinkt. Er will dir glauben. Er kann noch nicht.", "weiter": "reden2", "folgen": {"flag": ["entlastet"]}}, "misserfolg": {"text": "„Das sagen alle“, schreit er. „Das macht es nicht besser!“", "weiter": "reden_panik"}}, {"text": "„Du hast es nicht vergessen. Das heißt, du bist kein Ungeheuer.“", "tag": "[Beruhigen]", "probe": {"id": "beruhigen", "dc": 12}, "erfolg": {"text": "Ein Laut, halb Schluchzen, halb Lachen. „Ein Ungeheuer könnte schlafen.“ Die Tür öffnet sich einen Spalt.", "weiter": "reden2", "folgen": {"flag": ["angenommen"]}}, "misserfolg": {"text": "Er antwortet nicht.", "weiter": "reden2"}}]}, "reden2": {"ort": "dorf", "text": "Die Tür öffnet sich. Rutger steht da, grau, abgemagert, die Fackel gesenkt. „Was soll ich jetzt tun? Mit all dem?“", "optionen": [{"text": "„Es jemandem erzählen. Nicht nur mir. Dem Priester, deiner Frau, irgendwem.“", "weiter": "ende_reden"}, {"text": "„Etwas tun, das es nicht wiedergutmacht, aber das Gegenteil davon ist.“", "wenn": {"flag": "entlastet"}, "weiter": "ende_tat"}, {"text": "„Es mit mir tragen. Komm morgen mit auf die Wache. Wir reden, während wir wach bleiben.“", "wenn": {"flag": "angenommen"}, "weiter": "ende_wache"}, {"text": "„Schlafen. Du musst schlafen. Ich hole die Kräuterfrau.“", "weiter": "ende_kraeuter"}]}, "gras": {"ort": "dorf", "text": "Rutger liegt im Gras. Seine Frau kniet neben ihm. Er sieht dich an. „Warum hast du mich nicht brennen lassen?“", "optionen": [{"text": "„Weil die Kinder in der Scheune auch nicht brennen sollten. Und du auch nicht.“", "weiter": "ende_reden"}, {"text": "Schweigen und seine Hand halten, bis es hell wird", "weiter": "ende_wache"}]}, "ende_reden": {"ort": "dorf", "text": "Rutger redet. Erst mit dir, dann mit Gerda, dann – nach Wochen – mit dem Priester. Er schläft nicht viel besser. Aber er schläft. An manchen Tagen sitzt er vor seinem Haus und schnitzt kleine Holzfiguren. Für jedes Kind eine. Er hat ihre Namen nie erfahren, also gibt er ihnen welche.", "ende": true, "folgen": {"chronik": ["rutger_reden", "Ich habe Rutger die Fackel abgenommen – mit Worten. Er schnitzt jetzt Figuren für die Kinder aus der Scheune."], "beute": {"stufe": 2, "text": "Eines Tages steht eine der Figuren vor deiner Tür, und noch etwas daneben:"}}}, "ende_tat": {"ort": "dorf", "text": "Rutger baut im Frühjahr eine Scheune für die Rabenfelser Flüchtlinge am Dorfrand. Ohne Lohn. Mit einer Tür, die von innen aufgeht. Er sagt niemandem, warum. Du weißt es.", "ende": true, "folgen": {"chronik": ["rutger_tat", "Rutger hat eine Scheune gebaut, deren Tür von innen aufgeht."], "beute": {"stufe": 1}}}, "ende_wache": {"ort": "dorf", "text": "Ihr steht von nun an manchmal zusammen Wache, nachts, wenn er nicht schlafen kann. Er redet wenig. Aber er ist nicht allein dabei. Manchmal ist das alles, was man jemandem geben kann.", "ende": true, "folgen": {"chronik": ["rutger_wache", "Ich stehe manchmal nachts mit Rutger Wache. Wir reden wenig."], "beute": {"stufe": 1}}}, "ende_kraeuter": {"ort": "dorf", "text": "Die Kräuterfrau gibt ihm Mohnsaft. Er schläft drei Tage. Danach ist er ruhiger – bis der Saft aufgebraucht ist. Dann kommt er wieder, um mehr zu holen. Manche Wunden schließt man nicht mit Kräutern.", "ende": true, "folgen": {"chronik": ["rutger_kraeuter", "Rutger schläft jetzt – mit Mohnsaft. Ich weiß nicht, ob das Hilfe war."]}}, "ende_gewalt": {"ort": "dorf", "text": "Die Tür kracht auf, Rutger schreit, die Fackel fällt ins Stroh. Das Haus brennt bis auf die Grundmauern. Rutger überlebt. Er wird nie wieder ein Wort mit dir reden.", "ende": true, "folgen": {"chronik": ["rutger_gewalt", "Ich habe zugelassen, dass sie Rutgers Tür eintraten. Sein Haus ist abgebrannt."], "dorf": {"holz": -30}}}}}}, {"id": "o_moosherz", "titel": "Die Feder der Kanzlerin", "kurz": "Morgen entscheidet der Kronrat über das Bauernrecht. Eine Stimme fehlt – und Irmentrud braucht jemanden, den am Hof niemand kennt.", "schwer": 2, "fundort": "moosherz", "def": {"start": "start", "szenen": {"start": {"ort": "stadt", "text": "In der Kanzlei riecht es nach Tinte und kaltem Wachs. Irmentrud, die Hofschreiberin, sieht nicht von ihren Papieren auf. „Morgen stimmt der Kronrat über das Bauernrecht ab. Wenn es durchkommt, darf jeder Bauer vor Gericht gegen seinen Herrn klagen. Wenn nicht, bleibt alles, wie es ist.“ Jetzt sieht sie auf. „Fünf Stimmen dafür, fünf dagegen. Eine schwankt: Freiherr von Brakel. Und ich brauche jemanden, den am Hof noch keiner kennt.“", "optionen": [{"text": "„Was ist an Brakel so besonders?“", "weiter": "brakel"}, {"text": "„Warum ist dir das so wichtig?“", "weiter": "warum"}, {"text": "„Was springt für mich dabei heraus?“", "weiter": "lohn", "ergebnis": "„Die Gunst einer Frau, die eines Tages Kanzlerin sein wird“, sagt sie trocken. „Und einen Brief mit dem Siegel des Königs, wenn du ihn brauchst.“"}]}, "warum": {"ort": "stadt", "text": "Irmentrud legt die Feder hin. „Mein Vater war Tuchhändler. Ein Herr hat ihm die Ware genommen und nie bezahlt. Vor Gericht hat der Richter gelacht – ein Bürger klagt gegen einen Edlen? Mein Vater hat sich ein Jahr später erhängt.“ Sie greift wieder zur Feder. „Es ist nicht persönlich. Es ist nur wahr.“", "optionen": [{"text": "„Erzähl mir von Brakel.“", "weiter": "brakel", "folgen": {"flag": ["vater"]}}]}, "lohn": {"ort": "stadt", "text": "„Also, hilfst du?“", "optionen": [{"text": "„Erzähl mir von Brakel.“", "weiter": "brakel"}]}, "brakel": {"ort": "stadt", "text": "„Brakel ist alt, fromm und hat Schulden. Die Gegenseite – Herzog Ansgar und seine Freunde – hat ihm angeboten, die Schulden zu übernehmen, wenn er dagegen stimmt. Bisher hat er abgelehnt. Bisher.“ Sie schiebt dir drei Möglichkeiten hin, wie man Karten hinlegt. „Überzeug ihn. Oder finde heraus, womit Ansgar ihn erpresst. Oder …“ Sie zögert. „In Ansgars Schreibstube liegt ein Brief, der beweist, dass er Stimmen kauft. Den könnte jemand holen.“", "optionen": [{"text": "Brakel aufsuchen und mit ihm reden", "weiter": "brakel_haus"}, {"text": "Sich in Ansgars Schreibstube schleichen", "weiter": "ansgar"}, {"text": "Erst am Markt herumhören – bei Mirela, der Seherin", "weiter": "mirela"}]}, "mirela": {"ort": "stadt", "text": "Mirela sitzt unter einem bunten Tuch, eine Hand voller Ringe. „Ah, der Neue vom Hof.“ Sie lächelt. „Du willst wissen, was Brakel nachts wach hält? Das kostet.“", "optionen": [{"text": "Ihren Preis herunterhandeln", "tag": "[Feilschen]", "probe": {"id": "feilschen", "dc": 12}, "erfolg": {"text": "„Na gut, weil du so hübsch feilschst.“ Sie beugt sich vor. „Brakels Sohn ist nicht tot, wie alle glauben. Er sitzt in Ansgars Kerker, wegen Spielschulden. Ansgar lässt ihn frei, wenn der Alte richtig stimmt.“", "weiter": "brakel_wissen", "folgen": {"flag": ["sohn"]}}, "misserfolg": {"text": "Sie lacht und zieht die Hand weg. „Komm wieder, wenn du Geld hast.“", "weiter": "brakel"}}, {"text": "Lesen, ob sie für beide Seiten arbeitet", "tag": "[Menschenkenntnis]", "probe": {"id": "menschenkenntnis", "dc": 13}, "erfolg": {"text": "Ihr Lächeln sitzt eine Spur zu fest. Sie wird Ansgar erzählen, dass du gefragt hast – noch heute. Du sagst ihr nichts Wichtiges und gehst.", "weiter": "brakel", "folgen": {"flag": ["mirela_falsch"]}}, "misserfolg": {"text": "Sie wirkt ehrlich. So ehrlich, wie man auf einem Markt sein kann.", "weiter": "brakel"}}]}, "brakel_wissen": {"ort": "stadt", "text": "Jetzt verstehst du Brakels Zögern. Es geht nicht um Geld. Es geht um seinen Sohn.", "optionen": [{"text": "Brakel aufsuchen", "weiter": "brakel_haus"}, {"text": "Den Sohn aus Ansgars Kerker holen", "weiter": "ansgar"}]}, "brakel_haus": {"ort": "stadt", "text": "Freiherr von Brakel empfängt dich in einem Zimmer mit leeren Wänden – die Bilder hat er verkauft. Er ist höflich, müde, alt. „Das Bauernrecht. Ja. Ich weiß, was richtig wäre. Die Frage ist nur, was richtig ist für einen Mann in meiner Lage.“", "optionen": [{"text": "„Recht ist nicht, was einem nützt. Recht ist, was man vor den Enkeln vertreten kann.“", "tag": "[Überreden]", "probe": {"id": "ueberreden", "dc": 14}, "erfolg": {"text": "Er sieht lange aus dem Fenster. „Meine Enkel …“ Dann, leise: „Ich habe keine Enkel. Noch nicht.“ Er sieht dich an. „Es gibt Dinge, die du nicht weißt.“", "weiter": "brakel_offen"}, "misserfolg": {"text": "„Schöne Worte“, sagt er. „Junge Worte. Ich war auch einmal jung.“ Er steht auf. Das Gespräch ist vorbei.", "weiter": "brakel_zu"}}, {"text": "„Ich weiß von Eurem Sohn.“", "wenn": {"flag": "sohn"}, "weiter": "brakel_sohn"}, {"text": "„Eine Ordnung, in der nur die Mächtigen recht bekommen, ist keine Ordnung. Es ist ein Aufschub.“", "tag": "[Altes Wissen]", "probe": {"id": "altes_wissen", "dc": 13}, "erfolg": {"text": "„Ein Aufschub“, wiederholt er. „Bis zum nächsten Aufstand. Ich habe den letzten gesehen.“ Er nickt langsam. Er ist überzeugt – aber nicht frei.", "weiter": "brakel_offen"}, "misserfolg": {"text": "Er hört höflich zu. Philosophie ist ein Luxus für Männer ohne Schulden.", "weiter": "brakel_zu"}}]}, "brakel_zu": {"ort": "stadt", "text": "Draußen auf der Treppe. Der Weg über Worte ist verbaut. Bleibt der andere.", "optionen": [{"text": "In Ansgars Schreibstube einbrechen", "weiter": "ansgar"}, {"text": "Zu Irmentrud zurück und gestehen, dass es nicht geklappt hat", "weiter": "ende_nein"}]}, "brakel_offen": {"ort": "stadt", "text": "„Ansgar hat meinen Sohn“, sagt Brakel schließlich. „Spielschulden. Wenn ich falsch stimme, sehe ich ihn nie wieder.“ Seine Hände zittern. „Du verlangst, dass ich mein Kind für ein Gesetz opfere.“", "optionen": [{"text": "„Ich hole ihn raus. Heute Nacht. Dann seid Ihr frei.“", "weiter": "ansgar", "folgen": {"flag": ["versprochen"]}}, {"text": "„Ja. Das verlange ich. Für tausend Kinder, die nach ihm kommen.“", "weiter": "ende_opfer"}, {"text": "„Dann stimmt, wie Ihr müsst. Ich verstehe.“", "weiter": "ende_nein"}]}, "brakel_sohn": {"ort": "stadt", "text": "Brakel wird kreidebleich. „Woher …?“ Dann sackt er zusammen. „Ja. Er lebt. Und er bleibt am Leben, solange ich dagegen stimme.“", "optionen": [{"text": "„Ich hole ihn raus. Heute Nacht.“", "weiter": "ansgar", "folgen": {"flag": ["versprochen"]}}, {"text": "„Dann stimmt dafür – und vertraut darauf, dass Ansgar es nicht wagt, ihm etwas zu tun, wenn alle davon wissen.“", "weiter": "oeffentlich"}]}, "oeffentlich": {"ort": "stadt", "text": "Brakel starrt dich an. „Du meinst … es öffentlich machen? Im Kronrat?“", "optionen": [{"text": "„Ein Gefangener, von dem jeder weiß, ist eine Schande. Ein Gefangener, von dem niemand weiß, ist ein Druckmittel.“", "tag": "[Überreden]", "probe": {"id": "ueberreden", "dc": 13}, "erfolg": {"text": "Ein langer Atemzug. „Gut. Dann sprechen wir morgen beide.“", "weiter": "ende_rat_offen"}, "misserfolg": {"text": "„Nein. Das ist zu gefährlich.“ Er schickt dich fort.", "weiter": "brakel_zu"}}]}, "ansgar": {"ort": "stadt", "text": "Nacht über Moosherz. Ansgars Stadthaus liegt hinter dem Dom, Wachen an der Vordertür. Der Hof ist dunkel.", "reise": {"minuten": 25, "weiter": "einbruch", "text": "Du schleichst durch die Gassen der Hauptstadt."}}, "einbruch": {"ort": "stadt", "text": "Die Hintertür ist verriegelt, ein altes Schloss. Ein Wächter geht alle paar Minuten vorbei.", "minispiel": {"art": "schloss", "schwer": 3, "titel": "Das Schloss knacken", "erfolg": {"text": "Das Schloss gibt nach. Du gleitest in einen dunklen Flur.", "weiter": "innen"}, "misserfolg": {"text": "Das Schloss klemmt. Schritte nähern sich!", "weiter": "erwischt"}}, "optionen": []}, "innen": {"ort": "stadt", "text": "Links die Schreibstube, rechts eine Treppe nach unten. Von unten Husten. Ein Gefangener. Oben Licht – jemand ist noch wach. Du hast Zeit für eins.", "optionen": [{"text": "Die Schreibstube: der Brief", "weiter": "brief"}, {"text": "Der Keller: Brakels Sohn", "weiter": "keller"}]}, "brief": {"ort": "stadt", "text": "Der Brief liegt im zweiten Fach, versiegelt mit Ansgars Wappen. Eine Liste: Namen, Summen, Stimmen. Brakel steht drauf. Und drei andere aus dem Kronrat.", "optionen": [{"text": "Den Brief mitnehmen und verschwinden", "weiter": "flucht", "folgen": {"flag": ["brief"]}}]}, "keller": {"ort": "stadt", "text": "Ein junger Mann, mager, an die Wand gekettet. „Wer bist du?“ – „Dein Vater schickt mich.“ Er weint.", "optionen": [{"text": "Die Kette lösen", "tag": "[Anpacken]", "probe": {"id": "anpacken", "dc": 12}, "erfolg": {"text": "Der Ring an der Wand gibt nach. Ihr schleicht die Treppe hoch.", "weiter": "flucht", "folgen": {"flag": ["sohn_frei"]}}, "misserfolg": {"text": "Zu laut. Oben gehen Türen auf.", "weiter": "erwischt"}}]}, "erwischt": {"ort": "stadt", "text": "Wachen mit Knüppeln und Laternen. „Ein Dieb!“", "gefahr": true, "minispiel": {"art": "kampf", "schwer": 2, "titel": "Flucht durch Moosherz", "gegner": "banditen", "dauer": 240, "kampfort": "stadt", "erfolg": {"text": "Du schlägst dich durch und verschwindest in den Gassen – mit leeren Händen, aber frei.", "weiter": "flucht"}, "misserfolg": {"text": "Sie werfen dich auf die Straße, nach einer gründlichen Tracht Prügel. Ansgar weiß jetzt, dass jemand an seiner Tür war.", "weiter": "ende_nein", "folgen": {"gefahr": 1}}}, "optionen": []}, "flucht": {"ort": "stadt", "text": "Morgengrauen. Der Kronrat tagt in einer Stunde.", "optionen": [{"text": "Mit dem Brief zu Irmentrud", "wenn": {"flag": "brief"}, "weiter": "ende_brief"}, {"text": "Brakels Sohn zu seinem Vater bringen", "wenn": {"flag": "sohn_frei"}, "weiter": "ende_sohn"}, {"text": "Mit leeren Händen zu Irmentrud", "weiter": "ende_nein"}]}, "ende_brief": {"ort": "stadt", "text": "Irmentrud liest den Brief im Kronrat vor. Ansgar tobt, drei Räte werden blass, der König lässt die Abstimmung verschieben. Das Bauernrecht kommt nicht durch – noch nicht. Aber Ansgars Stimmenkauf ist ans Licht gekommen. „Das Gesetz braucht noch einen Winter“, sagt Irmentrud. „Ansgar braucht jetzt einen sehr guten Anwalt.“ Sie lächelt zum ersten Mal.", "ende": true, "folgen": {"chronik": ["moosherz_brief", "Ich habe in Moosherz einen Brief gestohlen, der einen Herzog bloßstellte."], "gunst": 6, "beute": {"stufe": 2, "text": "Irmentrud drückt dir ein Päckchen in die Hand:"}}}, "ende_sohn": {"ort": "stadt", "text": "Brakel umarmt seinen Sohn vor allen. Eine Stunde später stimmt er für das Bauernrecht. Es kommt durch, mit einer Stimme Mehrheit. Ab heute darf jeder Bauer im Königreich gegen seinen Herrn klagen. Ansgar hat einen neuen Feind – und ahnt, wer es ist.", "ende": true, "folgen": {"chronik": ["moosherz_bauernrecht", "Ich habe Brakels Sohn befreit. Das Bauernrecht ist Gesetz."], "gunst": 10, "beute": {"stufe": 2, "text": "Brakel schenkt dir, was ihm von seinem Vermögen geblieben ist:"}}}, "ende_rat_offen": {"ort": "stadt", "text": "Im Kronrat erhebt sich Brakel und spricht von seinem Sohn in Ansgars Kerker. Totenstille. Der König lässt den jungen Mann noch am selben Tag holen. Das Bauernrecht kommt durch. Ansgar verlässt den Hof. Manchmal ist Licht die schärfste Waffe.", "ende": true, "folgen": {"chronik": ["moosherz_licht", "Ich habe Brakel überzeugt, seine Erpressung öffentlich zu machen. Das Bauernrecht ist Gesetz."], "gunst": 12, "beute": {"stufe": 2}}}, "ende_opfer": {"ort": "stadt", "text": "Brakel stimmt dafür. Das Bauernrecht kommt durch. Drei Tage später findet man seinen Sohn tot in einem Graben vor der Stadt. Spielschulden, heißt es. Irmentrud zündet eine Kerze für ihn an. „Gesetze“, sagt sie, „werden immer mit fremdem Blut geschrieben.“", "ende": true, "folgen": {"chronik": ["moosherz_opfer", "Ich habe von Brakel verlangt, seinen Sohn für ein Gesetz zu opfern. Er hat es getan."], "gunst": 8}}, "ende_nein": {"ort": "stadt", "text": "Der Kronrat lehnt das Bauernrecht ab, fünf zu sechs. Irmentrud nimmt es ohne Regung hin. „Nächstes Jahr“, sagt sie. „Oder das danach.“ Draußen auf dem Markt geht das Leben weiter, als sei nichts gewesen. Für die meisten ist auch nichts gewesen.", "ende": true, "folgen": {"chronik": ["moosherz_nein", "In Moosherz ist das Bauernrecht gescheitert. Ich war dabei."]}}}}}, {"id": "o_furtenau", "titel": "Die Karren ohne Licht", "kurz": "Jede dritte Nacht rumpeln verhüllte Karren über die Furt nach Norden. Der Fährmann schweigt – ausgerechnet er.", "schwer": 2, "fundort": "furtenau", "def": {"start": "start", "szenen": {"start": {"ort": "stadt", "text": "Im Furtkrug flüstert man von den Karren ohne Licht. Jede dritte Nacht rumpeln sie über die Furt nach Norden, Richtung Rabenfels, verhüllt, ohne Laterne. Fährmann Gerwin, der sonst jeden Reisenden kennt, sagt nichts dazu. Hedda, die Wirtin, stellt dir einen Krug hin: „Wenn du rausfindest, was das ist, sag es mir zuerst. Mein Sohn dient beim Grafen.“", "optionen": [{"text": "Gerwin direkt fragen", "weiter": "gerwin"}, {"text": "Nachts an der Furt auf die Lauer legen", "weiter": "lauer"}, {"text": "Die Spuren der Karren bei Tag untersuchen", "weiter": "spuren"}]}, "spuren": {"ort": "fluss", "text": "Am Ufer, wo die Karren aus dem Wasser kommen: tiefe Radspuren, schwer beladen nach Norden. Aber zurück nach Süden kommen sie leicht. Und im Schlamm etwas anderes.", "minispiel": {"art": "spuren", "schwer": 2, "titel": "Spuren lesen", "erfolg": {"text": "Fußspuren neben den Karren – kleine. Kinderfüße. Und ein Stück Stoff am Gestrüpp, verkrustet mit etwas Gelbem. Eiter.", "weiter": "nachdenken", "folgen": {"flag": ["kinder", "krank"]}}, "misserfolg": {"text": "Du erkennst nur Räder und Hufe. Schwer nach Norden, leicht zurück. Was bringen sie hin?", "weiter": "nachdenken"}}, "optionen": []}, "gerwin": {"ort": "fluss", "text": "Gerwin flickt ein Netz und sieht nicht auf. „Karren? Ich sehe viele Karren.“", "optionen": [{"text": "„Du zählst beim Reden Münzen. Wie viel bekommst du fürs Schweigen?“", "tag": "[Menschenkenntnis]", "probe": {"id": "menschenkenntnis", "dc": 13}, "erfolg": {"text": "Seine Hand erstarrt in der Tasche. Lange Stille. „Nichts“, sagt er dann. „Ich bekomme nichts. Ich mache es umsonst. Und jetzt geh.“ Umsonst? Gerwin?", "weiter": "nachdenken", "folgen": {"flag": ["gerwin_umsonst"]}}, "misserfolg": {"text": "„Ich zähle, wie viele Fragen du noch stellst, bevor ich dich in den Fluss werfe.“", "weiter": "nachdenken"}}, {"text": "Ihm drohen, ihn beim Vogt zu melden", "tag": "[Einschüchtern]", "probe": {"id": "einschuechtern", "dc": 14}, "erfolg": {"text": "Er wird weiß. „Tu das nicht. Bitte. Da hängen Leben dran. Nicht meins.“", "weiter": "nachdenken", "folgen": {"flag": ["gerwin_umsonst"]}}, "misserfolg": {"text": "„Melde mich doch. Der Vogt kommt jeden Monat zum Essen.“", "weiter": "nachdenken"}}]}, "nachdenken": {"ort": "stadt", "text": "Was weißt du? Karren nach Norden, schwer beladen. Zurück leicht. Gerwin schweigt, ohne Geld zu nehmen. In Rabenfels hält der Graf seine Grenze geschlossen – keiner darf raus. Und Gerwins Frau stammt aus Rabenfels.", "raetsel": {"frage": "Wenn niemand Rabenfels verlassen darf und die Karren schwer nach Norden fahren und leicht zurückkommen: Wen holen sie heraus?", "antworten": ["menschen", "flüchtlinge", "fluechtlinge", "kranke", "leute", "flüchtende", "kinder", "familien"], "hinweise": ["Leicht heißt nicht leer.", "Was darf Rabenfels nicht verlassen?"], "versuche": 3, "erfolg": {"text": "Menschen. Sie bringen Vorräte hin und schmuggeln Leute heraus, versteckt unter leeren Säcken. Leicht ist der Karren nur, wenn man nicht weiß, was ein Kind wiegt.", "weiter": "lauer", "folgen": {"flag": ["geloest"]}}, "misserfolg": {"text": "Du kommst nicht drauf. Aber heute Nacht fährt wieder ein Karren.", "weiter": "lauer"}}, "optionen": []}, "lauer": {"ort": "fluss", "text": "Nacht an der Furt. Nebel auf dem Wasser, Frösche. Du liegst im Schilf und wartest.", "reise": {"minuten": 40, "weiter": "karren", "text": "Du wartest im Schilf an der Furt."}}, "karren": {"ort": "fluss", "text": "Ein Karren, ohne Licht, zwei Maultiere, ein Kutscher mit Kapuze. Mitten in der Furt bleibt er stecken. Unter der Plane: Husten. Ein Kind fängt an zu weinen und wird sofort still gemacht. Und vom Nordufer: Pferdegetrappel. Grenzreiter aus Rabenfels.", "optionen": [{"text": "Dem Kutscher helfen, den Karren freizubekommen", "weiter": "freimachen"}, {"text": "Die Grenzreiter ablenken", "weiter": "ablenken"}, {"text": "Abwarten und beobachten", "weiter": "beobachten"}]}, "freimachen": {"ort": "fluss", "text": "Das Rad steckt zwischen zwei Steinen. Der Kutscher – es ist Gerwin – zerrt verzweifelt. Die Reiter kommen näher.", "minispiel": {"art": "axt", "schwer": 2, "titel": "Das Rad freihebeln", "erfolg": {"text": "Mit einem Ruck kommt der Karren frei. Gerwin starrt dich an, dann treibt er die Maultiere ans Südufer.", "weiter": "sued"}, "misserfolg": {"text": "Zu spät. Die Reiter sind da.", "weiter": "reiter"}}, "optionen": []}, "ablenken": {"ort": "fluss", "text": "Du musst sie weglocken – schnell.", "optionen": [{"text": "Laut rufend in die Gegenrichtung laufen", "tag": "[Flink]", "probe": {"id": "flink", "dc": 13}, "erfolg": {"text": "Die Reiter folgen dir ins Schilf, fluchend, und verlieren dich im Nebel. Als du zurückkommst, ist der Karren fort.", "weiter": "sued"}, "misserfolg": {"text": "Einer folgt dir, die anderen reiten weiter zum Karren.", "weiter": "reiter"}}]}, "beobachten": {"ort": "fluss", "text": "Die Reiter umstellen den Karren. Ihr Anführer reißt die Plane weg. Darunter: sechs Menschen. Zwei Kinder, eine Frau mit eitrigen Wunden, drei Männer. „Seuchenflüchtlinge“, sagt der Anführer. „In Rabenfels ist das Fleckfieber ausgebrochen. Der Graf hat die Grenze geschlossen, damit es sich nicht ausbreitet. Und ihr bringt es in den Süden.“", "optionen": [{"text": "Eingreifen", "weiter": "reiter"}, {"text": "Weiter zusehen", "weiter": "ende_reiter"}]}, "reiter": {"ort": "fluss", "text": "Drei Reiter, Schwerter gezogen. Der Anführer: „Zurück nach Norden mit ihnen. Oder sie bleiben hier liegen.“ Gerwin steht zwischen ihnen und dem Karren. „Das sind Kinder!“ – „Das sind Kranke. Wie viele willst du in Furtenau begraben?“ Er hat nicht ganz unrecht. Das ist das Furchtbare.", "optionen": [{"text": "„Lasst sie durch. Ich bringe sie in Quarantäne, abseits der Stadt.“", "tag": "[Überreden]", "probe": {"id": "ueberreden", "dc": 14}, "erfolg": {"text": "Der Anführer zögert. „Du nimmst das auf dich? Wenn das Fieber nach Furtenau kommt, hängt man dich.“ Du nickst. Er spuckt aus und wendet sein Pferd.", "weiter": "quarantaene"}, "misserfolg": {"text": "„Nein.“ Er hebt das Schwert.", "weiter": "kampf"}}, {"text": "Die Waffe ziehen", "weiter": "kampf"}, {"text": "„Bringt sie zurück. Er hat recht.“", "weiter": "ende_zurueck"}]}, "kampf": {"ort": "fluss", "text": "Stahl über dem Wasser, Maultiere scheuen, Kinder schreien.", "gefahr": true, "minispiel": {"art": "kampf", "schwer": 2, "titel": "Kampf in der Furt", "gegner": "banditen", "dauer": 300, "kampfort": "fluss", "erfolg": {"text": "Die Reiter fliehen nach Norden. Gerwin bringt den Karren ans Südufer, zitternd.", "weiter": "sued"}, "misserfolg": {"text": "Du wirst niedergeschlagen. Als du aufwachst, sind Reiter und Karren fort – nach Norden.", "weiter": "ende_zurueck", "folgen": {"gefahr": 1}}}, "optionen": []}, "sued": {"ort": "fluss", "text": "Am Südufer, im Schutz der Weiden. Gerwin hebt die Plane. Sechs Menschen, eine Frau mit Fieberflecken am Hals. „Meine Schwägerin“, sagt er. „Der Rest sind Nachbarn. Wir bringen sie in die alte Fischerhütte und dann weiter.“ Er sieht dich an. „Weiter. Nach Furtenau. Auf den Markt. Unter Leute.“", "optionen": [{"text": "„Nein. Erst Quarantäne. Vierzig Tage in der Hütte.“", "weiter": "quarantaene"}, {"text": "„Ilsabe, die Kräuterfrau, muss sie sehen.“", "weiter": "ilsabe"}, {"text": "Hedda erzählen, was du gefunden hast", "weiter": "ende_hedda"}]}, "ilsabe": {"ort": "stadt", "text": "Ilsabe kommt in der Dämmerung, ein Tuch vor dem Mund. Sie untersucht die Frau lange. „Fleckfieber. Läuse tragen es. Wenn man die Kleider verbrennt und sie wäscht, breitet es sich nicht aus. Die anderen sind nur erschöpft.“ Sie sieht Gerwin an. „Du hättest sie fast auf den Markt gebracht.“", "optionen": [{"text": "„Dann machen wir es richtig.“", "weiter": "quarantaene", "folgen": {"flag": ["ilsabe"]}}]}, "quarantaene": {"ort": "fluss", "text": "Die alte Fischerhütte, abseits. Kleider brennen, Wasser kocht. Gerwin bringt Essen, Ilsabe Kräuter. In der Stadt ahnt niemand etwas. Aber du hast etwas auf dich genommen: Wenn es schiefgeht, bist du schuld.", "optionen": [{"text": "Die Sache dem Stadtrat melden – offen", "weiter": "ende_offen"}, {"text": "Schweigen und abwarten, bis die vierzig Tage um sind", "weiter": "ende_schweigen"}]}, "ende_offen": {"ort": "stadt", "text": "Der Stadtrat tobt, dann rechnet er. Vierzig Tage, eine Hütte, eine Kräuterfrau – das ist billiger als ein Krieg mit dem Grafen oder eine Seuche. Die Flüchtlinge dürfen bleiben. Gerwin sagt dir am Abend, er habe nicht gewusst, dass man so etwas laut sagen kann.", "ende": true, "folgen": {"chronik": ["furtenau_offen", "Ich habe die Seuchenflüchtlinge in Furtenau dem Rat gemeldet. Sie dürfen bleiben – nach vierzig Tagen."], "beute": {"stufe": 2, "text": "Gerwin gibt dir etwas aus seinem Lagerhaus:"}}}, "ende_schweigen": {"ort": "stadt", "text": "Vierzig Tage. Niemand stirbt, niemand steckt sich an. Gerwins Schwägerin überlebt. Die Karren ohne Licht fahren weiter, jetzt mit einem Halt bei der Fischerhütte. Du weißt, dass es Glück war. Glück und Ilsabes Kräuter.", "ende": true, "folgen": {"chronik": ["furtenau_schweigen", "Ich habe geholfen, Seuchenflüchtlinge heimlich nach Furtenau zu bringen. Es ist gut gegangen."], "beute": {"stufe": 1}}}, "ende_hedda": {"ort": "stadt", "text": "Hedda hört zu, ohne zu unterbrechen. Dann steht sie auf. „Mein Sohn ist bei den Grenzreitern“, sagt sie. „Wenn er einen von diesen Karren aufhält, ist er ein Held. Wenn er einen durchlässt, ist er ein Deserteur.“ Sie schenkt dir nach. „Danke, dass du es mir gesagt hast. Jetzt muss ich mit dem Wissen leben.“", "ende": true, "folgen": {"chronik": ["furtenau_hedda", "Ich habe Hedda erzählt, was über die Furt fährt. Jetzt weiß sie, wovor ihr Sohn steht."]}}, "ende_zurueck": {"ort": "fluss", "text": "Die Reiter treiben den Karren zurück nach Norden. Gerwin steht bis zu den Knien im Wasser und sieht ihnen nach. Er wird nie wieder ein Wort mit dir reden. Ob du Furtenau vor einer Seuche bewahrt hast oder sechs Menschen den Tod gebracht – beides kann wahr sein.", "ende": true, "folgen": {"chronik": ["furtenau_zurueck", "Die Flüchtlinge wurden nach Rabenfels zurückgebracht. Ich habe es zugelassen."]}}, "ende_reiter": {"ort": "fluss", "text": "Die Reiter nehmen den Karren mit. Gerwin wird abgeführt. Am nächsten Morgen ist das Lagerhaus versiegelt. Niemand im Furtkrug redet mehr über Karren ohne Licht.", "ende": true, "folgen": {"chronik": ["furtenau_reiter", "Ich habe an der Furt zugesehen. Gerwin sitzt jetzt in Rabenfels."]}}}}}, {"id": "o_hollerbrueck", "titel": "Die Steine am Hang", "kurz": "Zwei Dörfer stehen sich an der Hollerbrücke mit Heugabeln gegenüber. Jemand hat die Grenzsteine versetzt.", "schwer": 1, "fundort": "hollerbrueck", "def": {"start": "start", "szenen": {"start": {"ort": "dorf", "text": "An der Hollerbrücke steht eine Menge mit Heugabeln, auf der anderen Seite Leute aus Ginsterhof mit Knüppeln. Dazwischen Kordula, die Brückenwächterin, die Hand am Schwert. „Jemand hat die Grenzsteine am Hang versetzt“, erklärt sie dir, ohne den Blick von den Männern zu nehmen. „Zwanzig Schritt weiter nach Ginsterhof. Jede Seite sagt, es war die andere. Wenn das so weitergeht, gibt es heute Tote.“", "optionen": [{"text": "Dazwischentreten und beide Seiten zum Reden bringen", "tag": "[Beruhigen]", "probe": {"id": "beruhigen", "dc": 13}, "erfolg": {"text": "„Wer zuschlägt, hat verloren, egal was die Steine sagen.“ Ein Moment Stille. Dann senkt einer die Heugabel. Dann noch einer. Kordula nickt dir zu.", "weiter": "pause"}, "misserfolg": {"text": "Jemand wirft einen Stein. Er trifft niemanden – diesmal. Kordula zieht blank, und das hält sie zurück. Vorerst.", "weiter": "pause", "folgen": {"flag": ["angespannt"]}}}, {"text": "Kordula fragen, was sie weiß", "weiter": "kordula"}]}, "kordula": {"ort": "dorf", "text": "Kordula streicht mit dem Daumen über die Narbe am Kinn. „Weiß? Nichts. Ich weiß nur, dass Anselm, der Müller, Schulden hat. Und dass ihm das Feld am Hang gehört. Und dass Tönnies, der Hirte, seit drei Tagen nicht mehr ins Dorf kommt.“", "optionen": [{"text": "Erst die Menge beruhigen", "weiter": "pause"}]}, "pause": {"ort": "dorf", "text": "Die Leute gehen auseinander, murrend. Kordula gibt dir einen Tag. „Wenn du bis morgen Abend nicht weißt, wer es war, entscheiden die Heugabeln.“", "optionen": [{"text": "Zum Müller Anselm", "weiter": "anselm"}, {"text": "Den Hirten Tönnies auf den Hängen suchen", "weiter": "toennies_weg"}, {"text": "Die Grenzsteine selbst ansehen", "weiter": "steine"}]}, "steine": {"ort": "berg", "text": "Die Steine am Hang. Alt, moosbewachsen – an der Unterseite. Oben ist das Moos abgerieben. Darunter der alte Abdruck im Boden, zwanzig Schritt hangaufwärts.", "minispiel": {"art": "spuren", "schwer": 2, "titel": "Den Boden lesen", "erfolg": {"text": "Frische Kratzspuren, ein Hebel wurde benutzt. Fußspuren: schwere Stiefel, ein Mann, der hinkt. Und Mehl. Feines, weißes Mehl in den Ritzen.", "weiter": "pause2", "folgen": {"flag": ["mehl"]}}, "misserfolg": {"text": "Jemand hat sie bewegt, das ist klar. Wer, verrät der Boden dir nicht.", "weiter": "pause2"}}, "optionen": []}, "pause2": {"ort": "dorf", "text": "Wohin jetzt?", "optionen": [{"text": "Zum Müller Anselm", "wenn": {"nicht_flag": "anselm_besucht"}, "weiter": "anselm"}, {"text": "Den Hirten Tönnies suchen", "wenn": {"nicht_flag": "toennies_besucht"}, "weiter": "toennies_weg"}, {"text": "Zu Kordula, um zu berichten", "weiter": "bericht"}]}, "anselm": {"ort": "dorf", "text": "Anselm klopft sich Mehl von der Jacke. Es ist keins da. „Die Steine? Ginsterhof war das, ganz sicher. Die wollen schon lange unser Weideland.“ Er redet zu schnell.", "optionen": [{"text": "Seine Nervosität deuten", "tag": "[Menschenkenntnis]", "probe": {"id": "menschenkenntnis", "dc": 12}, "erfolg": {"text": "Er hat Angst – nicht vor Ginsterhof. Vor seiner Frau, die hinter ihm am Mehlsack steht und zuhört. Was er verbirgt, verbirgt er vor ihr.", "weiter": "anselm2", "folgen": {"flag": ["anselm_angst", "anselm_besucht"]}}, "misserfolg": {"text": "Er ist ein ängstlicher Mann. Das allein beweist nichts.", "weiter": "anselm2", "folgen": {"flag": ["anselm_besucht"]}}}, {"text": "„In den Ritzen der Steine war Mehl.“", "wenn": {"flag": "mehl"}, "weiter": "anselm_mehl"}]}, "anselm_mehl": {"ort": "dorf", "text": "Anselm wird grau wie sein Mehl. Seine Frau lässt den Sack fallen. „Anselm?“", "optionen": [{"text": "Ihn allein sprechen", "weiter": "anselm_allein"}, {"text": "Vor seiner Frau weiterfragen", "weiter": "anselm_frau"}]}, "anselm2": {"ort": "dorf", "text": "Anselm wischt sich die Stirn.", "optionen": [{"text": "Ihn allein sprechen", "weiter": "anselm_allein"}, {"text": "Gehen", "weiter": "pause2", "folgen": {"flag": ["anselm_besucht"]}}]}, "anselm_allein": {"ort": "dorf", "text": "Hinter der Mühle bricht er zusammen. „Ich schulde dem Händler aus Goldacker vierzig Silber. Mit dem Feld bis zum alten Stein kann ich die Mühle nicht halten. Mit zwanzig Schritt mehr Acker vielleicht. Ich dachte, Ginsterhof merkt es nicht. Es sind doch nur zwanzig Schritt.“ Er weint. „Meine Frau darf es nicht wissen. Sie würde mich verlassen.“", "optionen": [{"text": "„Du musst es vor allen sagen. Sonst sterben morgen Menschen für deine zwanzig Schritt.“", "weiter": "gestaendnis", "folgen": {"flag": ["anselm_beichte"]}}, {"text": "„Lass uns einen Weg finden, wie du die Schulden abbezahlst – und dann sagst du es.“", "tag": "[Überreden]", "probe": {"id": "ueberreden", "dc": 12}, "erfolg": {"text": "Er nickt, zitternd. „Wenn jemand neben mir steht …“", "weiter": "gestaendnis", "folgen": {"flag": ["anselm_beichte", "hilfe"]}}, "misserfolg": {"text": "„Nein! Niemand darf es wissen!“ Er rennt in die Mühle.", "weiter": "pause2"}}, {"text": "„Ich sage nichts. Aber setz die Steine heute Nacht zurück.“", "weiter": "ende_heimlich"}]}, "anselm_frau": {"ort": "dorf", "text": "Vor seiner Frau gesteht er alles, stammelnd. Sie hört zu, die Arme verschränkt. Dann sagt sie ruhig: „Vierzig Silber. Und du hast es mir nicht gesagt.“ Sie dreht sich um und geht ins Haus. Die Tür bleibt offen.", "optionen": [{"text": "Anselm zur Brücke bringen", "weiter": "gestaendnis", "folgen": {"flag": ["anselm_beichte"]}}]}, "toennies_weg": {"ort": "berg", "text": "Die Hänge über dem Fluss. Schafe, Wind, ein einsamer Pfiff, der eine Melodie sein könnte.", "reise": {"minuten": 30, "weiter": "toennies"}}, "toennies": {"ort": "berg", "text": "Tönnies sitzt auf einem Felsen und schnitzt. „Ich hab gewusst, dass jemand kommt“, sagt er. „Der Bussard ist dreimal über mich gekreist.“ Er hat etwas gesehen, das merkst du. Er hat Angst, es zu sagen.", "optionen": [{"text": "Ihn reden lassen, ohne zu drängen", "tag": "[Beruhigen]", "probe": {"id": "beruhigen", "dc": 11}, "erfolg": {"text": "Du setzt dich, siehst den Schafen zu. Nach langer Zeit: „Es war der Müller. Nachts, mit einer Stange. Er hat geweint dabei.“ Tönnies sieht dich an. „Er ist kein schlechter Mann. Er ist nur ein ängstlicher.“", "weiter": "pause2", "folgen": {"flag": ["zeuge", "toennies_besucht"]}}, "misserfolg": {"text": "„Ich hab nichts gesehen“, sagt er und pfeift weiter.", "weiter": "pause2", "folgen": {"flag": ["toennies_besucht"]}}}, {"text": "„Wenn du schweigst und morgen jemand stirbt, wirst du das nie mehr los.“", "tag": "[Einschüchtern]", "probe": {"id": "einschuechtern", "dc": 13}, "erfolg": {"text": "Er wird blass. „Der Müller. Mit einer Stange. Bitte sag nicht, dass ich es war, der es verraten hat.“", "weiter": "pause2", "folgen": {"flag": ["zeuge", "toennies_besucht"]}}, "misserfolg": {"text": "Er dreht sich weg und geht zu seinen Schafen.", "weiter": "pause2", "folgen": {"flag": ["toennies_besucht"]}}}]}, "bericht": {"ort": "dorf", "text": "Kordula hört zu. „Und?“", "optionen": [{"text": "„Es war Anselm. Er hat Schulden.“", "wenn": {"flag": "zeuge"}, "weiter": "anklage"}, {"text": "„Es war Anselm. Er will es selbst sagen.“", "wenn": {"flag": "anselm_beichte"}, "weiter": "gestaendnis"}, {"text": "„Ich weiß es nicht.“", "weiter": "ende_heugabeln"}]}, "anklage": {"ort": "dorf", "text": "An der Brücke, beide Dörfer versammelt. Du sagst, was du weißt. Anselm wird gepackt, sein Gesicht ist leer. Jemand aus Ginsterhof ruft: „Hängt ihn!“ Und Kordula, die Hand am Schwert, sieht dich an. Sie wartet, was du sagst.", "optionen": [{"text": "„Er hat aus Angst gehandelt, nicht aus Bosheit. Er soll den Schaden bezahlen, nicht mit seinem Leben.“", "tag": "[Überreden]", "probe": {"id": "ueberreden", "dc": 13}, "erfolg": {"text": "Murren, aber die Hände lassen Anselm los. Der Rat beider Dörfer beschließt: Er arbeitet ein Jahr für Ginsterhof umsonst. Seine Mühle behält er.", "weiter": "ende_urteil"}, "misserfolg": {"text": "Die Wut ist größer als deine Worte. Kordula muss dazwischengehen, um Blut zu verhindern.", "weiter": "ende_hart"}}]}, "gestaendnis": {"ort": "dorf", "text": "Anselm steht auf der Brücke vor beiden Dörfern. Er sagt es. Alles. Die Schulden, die Nacht, die zwanzig Schritt. Am Ende steht seine Frau neben ihm. Sie hält seine Hand nicht – aber sie steht da.", "optionen": [{"text": "„Jetzt lasst uns reden, wie er die Schuld begleicht.“", "weiter": "ende_beichte"}]}, "ende_beichte": {"ort": "dorf", "text": "Ginsterhof bekommt seine Steine zurück und ein Jahr lang Mehl umsonst. Anselm verkauft eine Kuh und zahlt den Händler aus Goldacker. Seine Frau redet eine Woche nicht mit ihm, dann wieder. Kordula sagt zu dir, an der Brücke, im Abendlicht: „Ich hätte es mit dem Schwert gelöst. Damals hätte ich das.“", "ende": true, "folgen": {"chronik": ["holler_beichte", "Ich habe Anselm dazu gebracht, vor zwei Dörfern zu gestehen. Niemand ist gestorben."], "beute": {"stufe": 2, "text": "Kordula gibt dir etwas aus ihrer Söldnerzeit:"}}}, "ende_urteil": {"ort": "dorf", "text": "Anselm arbeitet ein Jahr für Ginsterhof. Er redet mit niemandem mehr in Hollerbrück. Tönnies, der dich verraten sah, wer es verraten hat, pfeift ein neues Lied, wenn du vorbeikommst. Es klingt traurig.", "ende": true, "folgen": {"chronik": ["holler_urteil", "Ich habe Anselm angeklagt und um Gnade gebeten. Er lebt – mit der Schande."], "beute": {"stufe": 1}}}, "ende_heimlich": {"ort": "dorf", "text": "In der Nacht stehen die Steine wieder an ihrem Platz. Am Morgen sagen beide Dörfer, die andere Seite habe eingelenkt. Keiner hat gewonnen, keiner verloren. Anselm hat weiter Schulden. Und du weißt etwas, das du niemandem sagen kannst.", "ende": true, "folgen": {"chronik": ["holler_heimlich", "Ich habe Anselms Geheimnis bewahrt. Die Steine stehen wieder – und die Schulden bleiben."]}}, "ende_hart": {"ort": "dorf", "text": "Kordula verhindert Blut, aber nur knapp. Anselm wird aus Hollerbrück gejagt, die Mühle fällt an seinen Gläubiger. Die Grenze ist wieder, wo sie war. Der Frieden auch – fast.", "ende": true, "folgen": {"chronik": ["holler_hart", "Anselm wurde verjagt. Die Steine stehen wieder."]}}, "ende_heugabeln": {"ort": "dorf", "text": "Am nächsten Abend gehen die Heugabeln los. Kordula hält die Brücke, verwundet. Es gibt keine Toten, nur gebrochene Knochen und einen Groll, der für Generationen reichen wird.", "ende": true, "folgen": {"chronik": ["holler_heugabeln", "An der Hollerbrücke wurde gekämpft. Ich habe es nicht verhindert."]}}}}}, {"id": "o_rabenfels", "titel": "Unter dem Rabenfelsen", "kurz": "Eine Küchenmagd auf der Burg hat etwas gehört, das sie nicht hätte hören dürfen: Gift, ein Rabenring und der Name des Königs.", "schwer": 3, "fundort": "rabenfels", "def": {"start": "start", "szenen": {"start": {"ort": "burg", "text": "Rabenfels ist ein Felsen mit einer Burg darauf und einem Dorf darunter, das immer im Schatten liegt. In der Küche der Burg, wo du dich als Tagelöhner hast einstellen lassen, zieht dich die Magd Wiebke in eine Ecke. „Du bist nicht von hier“, flüstert sie. „Gut. Ich muss es jemandem sagen, der nicht von hier ist.“ Sie hat gehört, wie Burgvogt Ragnolf nachts mit einem Fremden sprach. Mit einem, der einen Rabenring trägt. Über Moosherz. Über Gift.", "optionen": [{"text": "„Erzähl mir alles.“", "weiter": "wiebke"}, {"text": "„Warum gehst du nicht zum Grafen?“", "weiter": "graf"}]}, "graf": {"ort": "burg", "text": "„Zum Grafen?“ Wiebke lacht erstickt. „Ragnolf ist seit dreißig Jahren seine rechte Hand. Wem glaubt er – ihm oder einer Küchenmagd?“ Sie zieht an ihrer Schürze. „Und wenn der Graf es weiß? Wenn er es befohlen hat?“", "optionen": [{"text": "„Dann erzähl mir alles.“", "weiter": "wiebke"}]}, "wiebke": {"ort": "burg", "text": "„Beim Erntedankfest in Moosherz soll der König Wein aus Rabenfels bekommen. Ein Geschenk, als Zeichen des Friedens. Ragnolf hat gesagt, der Wein wird der letzte sein, den Ottokar trinkt. Der Fremde soll das Gift bringen. Heute Nacht. In die Kapelle.“ Sie zittert. „Kaplan Severin weiß es auch. Er hat Ragnolf die Beichte abgenommen.“", "optionen": [{"text": "Den Kaplan aufsuchen", "weiter": "severin"}, {"text": "Heute Nacht in der Kapelle auf der Lauer liegen", "weiter": "nacht"}, {"text": "Sich in Ragnolfs Kammer schleichen und Beweise suchen", "weiter": "kammer"}, {"text": "An den Rabenbrief aus Kapitel 4 denken – du hast ihn schon einmal gesehen", "wenn": {"wissen": "chronik_4"}, "weiter": "rabenbrief"}]}, "rabenbrief": {"ort": "burg", "text": "Ein Rabenring. Du erinnerst dich an den Brief, den du auf dem Weg nach Moosherz gefunden hast – an das Siegel mit dem Raben. Dieselben Leute. Der Plan reicht weiter zurück, als Wiebke ahnt. Und weiter hinauf.", "optionen": [{"text": "Den Kaplan aufsuchen", "weiter": "severin", "folgen": {"flag": ["rabe_bekannt"]}}, {"text": "Heute Nacht in der Kapelle lauern", "weiter": "nacht", "folgen": {"flag": ["rabe_bekannt"]}}]}, "severin": {"ort": "burg", "text": "Kaplan Severin kniet in der Kapelle. Er erschrickt, als du von Gift sprichst. „Das Beichtgeheimnis“, sagt er. „Ich darf nichts sagen. Gott wird richten.“ Seine Hände zittern.", "optionen": [{"text": "„Gott richtet nach der Tat. Du kannst sie verhindern.“", "tag": "[Überreden]", "probe": {"id": "ueberreden", "dc": 13}, "erfolg": {"text": "Er schließt die Augen. „Ich sage nichts. Aber heute Nacht lasse ich die Sakristeitür offen. Hinter dem Wandteppich kann man alles hören.“", "weiter": "nacht", "folgen": {"flag": ["sakristei"]}}, "misserfolg": {"text": "„Geh“, sagt er. „Bitte geh.“ Aber er hat nicht gesagt, du sollst nicht wiederkommen.", "weiter": "nacht"}}, {"text": "„Wenn der König stirbt, gibt es Krieg. Wie viele Beichten wirst du dann hören? Von Witwen?“", "tag": "[Einschüchtern]", "probe": {"id": "einschuechtern", "dc": 12}, "erfolg": {"text": "Er bricht zusammen. „Der Fremde heißt Corvin. Er kommt aus Krähenstieg, von den Graumänteln. Mitternacht. Ich lasse die Sakristei offen.“", "weiter": "nacht", "folgen": {"flag": ["sakristei", "corvin"]}}, "misserfolg": {"text": "Er schüttelt nur den Kopf, weinend.", "weiter": "nacht"}}]}, "kammer": {"ort": "burg", "text": "Ragnolfs Kammer liegt im Turm. Die Wache macht alle Viertelstunde ihre Runde. Die Tür ist verschlossen.", "minispiel": {"art": "schloss", "schwer": 3, "titel": "Ragnolfs Tür", "erfolg": {"text": "Drinnen: Karten von Moosherz, eine Liste mit Namen von Höflingen – und ein Fläschchen, leer, mit eingeritztem Raben. Und ein Brief: „Der Wein muss vor dem dritten Tag des Festes geöffnet werden.“", "weiter": "nacht", "folgen": {"flag": ["beweis"]}}, "misserfolg": {"text": "Schritte auf der Treppe! Du verschwindest gerade noch rechtzeitig in einer Nische.", "weiter": "nacht"}}, "optionen": []}, "nacht": {"ort": "burg", "text": "Mitternacht. Die Burg schläft. Nur der Wind heult um den Felsen.", "reise": {"minuten": 20, "weiter": "kapelle", "text": "Du schleichst durch die dunklen Gänge der Burg."}}, "kapelle": {"ort": "burg", "text": "In der Kapelle: zwei Gestalten im Kerzenlicht. Ragnolf, leise wie immer. Und ein Mann in grauem Mantel, mit einem Ring, der im Licht wie ein Rabenauge blitzt. Er stellt ein Kästchen auf den Altar. „Nachtschatten und Eisenhut. Er wird einschlafen und nicht aufwachen. Niemand wird es schmecken.“", "optionen": [{"text": "Hinter dem Wandteppich bleiben und alles hören", "wenn": {"flag": "sakristei"}, "weiter": "lauschen"}, {"text": "Hervortreten und beide stellen", "weiter": "stellen"}, {"text": "Warten, bis sie gehen, dann das Kästchen stehlen", "weiter": "stehlen"}]}, "lauschen": {"ort": "burg", "text": "Du hörst alles. Namen. Daten. Und dann: „Der Graf weiß nichts?“ – „Der Graf ist alt und weich“, sagt Ragnolf. „Wenn Ottokar tot ist, wird der Graf König sein, ob er will oder nicht. Und ich werde neben ihm stehen.“ Der Graf ist unschuldig. Das ändert alles.", "optionen": [{"text": "Zum Grafen gehen – sofort, mit dem, was du gehört hast", "weiter": "graf_nacht"}, {"text": "Das Kästchen nach dem Treffen stehlen", "weiter": "stehlen", "folgen": {"flag": ["graf_unschuldig"]}}]}, "stellen": {"ort": "burg", "text": "Du trittst hervor. Ragnolf dreht sich langsam um. „Der Tagelöhner.“ Er lächelt nicht. „Corvin. Töte ihn.“", "optionen": [{"text": "„Ich bin nicht allein. Die halbe Burg weiß Bescheid.“", "tag": "[Einschüchtern]", "probe": {"id": "einschuechtern", "dc": 15}, "erfolg": {"text": "Corvin zögert. Ragnolf durchschaut den Bluff – aber Corvin nicht. Der Graumantel flieht durch das Seitentor. Ragnolf steht allein vor dir.", "weiter": "ragnolf_allein"}, "misserfolg": {"text": "„Lügner“, sagt Ragnolf.", "weiter": "kampf"}}, {"text": "Die Waffe ziehen", "weiter": "kampf"}]}, "kampf": {"ort": "burg", "text": "Corvin zieht zwei Klingen, Ragnolf ruft die Wache. Von überall kommen Schritte.", "gefahr": true, "minispiel": {"art": "kampf", "schwer": 3, "titel": "Kampf in der Burgkapelle", "gegner": "banditen", "dauer": 480, "kampfort": "burg", "erfolg": {"text": "Corvin liegt am Boden, Ragnolf ist durch eine Geheimtür geflohen. Auf dem Altar steht das Kästchen mit dem Gift.", "weiter": "nach_kampf"}, "misserfolg": {"text": "Du schlägst dich bis zum Tor durch und fliehst über den Felsen ins Tal – verwundet, gejagt, aber mit dem Kästchen.", "weiter": "flucht", "folgen": {"gefahr": 2}}}, "optionen": []}, "ragnolf_allein": {"ort": "burg", "text": "Ragnolf und du, allein in der Kapelle. Er greift nicht an. „Was willst du? Geld? Ich kann dich reich machen.“ Er meint es ernst.", "optionen": [{"text": "„Ich will, dass du dich dem Grafen stellst.“", "weiter": "graf_nacht"}, {"text": "„Du wirst dich selbst anzeigen. Sonst trägt Wiebke die Liste mit deinen Namen nach Moosherz.“", "tag": "[Überreden]", "probe": {"id": "ueberreden", "dc": 15}, "erfolg": {"text": "Lange Stille. Dann nimmt er sein Schwert ab und legt es auf den Altar. „Der Graf soll es von mir hören. Nicht von einer Magd.“", "weiter": "ende_gestaendnis"}, "misserfolg": {"text": "Er lacht. „Dann stirbt sie. Und du mit ihr.“ Er zieht.", "weiter": "kampf"}}, {"text": "Das Geld nehmen", "weiter": "ende_bestochen"}]}, "stehlen": {"ort": "burg", "text": "Die beiden gehen. Das Kästchen steht auf dem Altar – unbewacht? Ein Faden spannt sich davor, an einer Glocke.", "minispiel": {"art": "nadel", "schwer": 3, "titel": "Den Faden umgehen", "erfolg": {"text": "Du hast das Kästchen. Niemand hat dich gehört.", "weiter": "flucht", "folgen": {"flag": ["gift"]}}, "misserfolg": {"text": "Die Glocke schellt!", "weiter": "kampf"}}, "optionen": []}, "nach_kampf": {"ort": "burg", "text": "Die Wachen stürmen herein – und mit ihnen Graf Wulfhard, im Nachthemd, ein Schwert in der Hand. Er sieht Corvin, das Kästchen, dich. „Was ist hier los?“", "optionen": [{"text": "Ihm alles erzählen", "weiter": "ende_graf"}]}, "graf_nacht": {"ort": "burg", "text": "Graf Wulfhard hört dich im Nachtgewand an, in seinem Schlafgemach, umgeben von Wachen. Er unterbricht nicht. Am Ende sitzt er sehr still. „Ragnolf hat mir das Leben gerettet. Zweimal. Und jetzt will er mich zum Königsmörder machen.“", "optionen": [{"text": "„Ihr müsst ihn aufhalten. Heute Nacht.“", "weiter": "ende_graf"}]}, "flucht": {"ort": "wald", "text": "Über den Felsen, durch den Wald, das Kästchen unter dem Hemd. Hinter dir Hunde.", "reise": {"minuten": 40, "weiter": "ende_flucht"}}, "ende_graf": {"ort": "burg", "text": "Ragnolf wird in der Morgendämmerung festgenommen, an der Stalltür, mit gepacktem Pferd. Corvin schweigt unter der Folter. Graf Wulfhard schickt einen Brief nach Moosherz – nicht mit Wein, sondern mit der Wahrheit. Ob König Ottokar ihm glaubt, ist eine andere Frage. Wiebke bekommt eine Stelle als Hausdame – und darf ihren Stallknecht heiraten.", "ende": true, "folgen": {"chronik": ["rabenfels_graf", "Ich habe in Rabenfels einen Giftanschlag auf König Ottokar aufgedeckt. Der Graf war unschuldig."], "gunst": 15, "welt": {"ort": "rabenfels", "art": "buendnis", "grund": "Du hast den Grafen vor seinem eigenen Vogt bewahrt"}, "beute": {"stufe": 2, "text": "Graf Wulfhard überreicht dir selbst:"}}}, "ende_gestaendnis": {"ort": "burg", "text": "Ragnolf geht selbst zum Grafen. Was in dieser Nacht gesprochen wurde, erfährt niemand. Am Morgen ist Ragnolf fort, verbannt, sagt man. Der Wein aus Rabenfels kommt nie in Moosherz an. Der Frieden hält. Noch.", "ende": true, "folgen": {"chronik": ["rabenfels_gestaendnis", "Ich habe Ragnolf gezwungen, sich dem Grafen zu stellen. Der Wein kam nie in Moosherz an."], "gunst": 10, "beute": {"stufe": 1}}}, "ende_flucht": {"ort": "wald", "text": "Du bringst das Kästchen nach Moosherz. Am Hof glaubt man dir – halb. König Ottokar lässt den Wein aus Rabenfels in den Fluss gießen und die Grenze verstärken. Krieg liegt in der Luft. In Rabenfels sucht man einen Tagelöhner mit deinem Gesicht.", "ende": true, "folgen": {"chronik": ["rabenfels_flucht", "Ich bin aus Rabenfels geflohen, mit dem Gift für den König unter dem Hemd."], "gunst": 8, "welt": {"ort": "rabenfels", "art": "rivalitaet", "grund": "Ein Giftanschlag auf den König kam aus Rabenfels"}}}, "ende_bestochen": {"ort": "burg", "text": "Ragnolf zahlt gut. Du verlässt Rabenfels reicher, als du gekommen bist. Wiebke sieht dich am Tor, und du kannst ihren Blick nicht erwidern. Was am Erntedankfest in Moosherz geschieht, liegt jetzt nicht mehr in deiner Hand. Nur auf deinem Gewissen.", "ende": true, "folgen": {"chronik": ["rabenfels_bestochen", "Ich habe Ragnolfs Geld genommen."], "beute": {"stufe": 2, "text": "In dem Beutel, den Ragnolf dir gibt, liegt mehr als Silber:"}}}}}}, {"id": "o_gast_brunnen", "titel": "Streit am fremden Brunnen", "kurz": "Zwei Frauen streiten am Brunnen. Weil du fremd bist, sollst du entscheiden.", "schwer": 1, "fundort": "spielerdorf", "def": {"start": "start", "szenen": {"start": {"ort": "dorf", "text": "Am Brunnen dieses Dorfes streiten zwei Frauen, laut genug, dass es das halbe Dorf hört. Die eine sagt, die andere habe nachts Wasser für ihren Garten geschöpft, obwohl der Brunnen seit dem trockenen Sommer kaum noch etwas gibt. Die andere sagt, das sei gelogen. Als sie dich sehen, verstummen sie. Ein Fremder. „Du hast nichts damit zu tun“, sagt die eine. „Genau deshalb“, sagt die andere, „soll er entscheiden.“", "optionen": [{"text": "Sich die beiden Geschichten anhören", "weiter": "hoeren"}, {"text": "Den Brunnen selbst untersuchen", "weiter": "brunnen"}]}, "hoeren": {"ort": "dorf", "text": "Die eine, Berthe, hat Spuren gesehen: nasse Erde am Morgen, eine Tropfspur zum Garten der anderen. Die andere, Oda, hat einen Säugling und einen kranken Mann. Sie sagt, sie habe nur für sie geschöpft, tagsüber, wie erlaubt.", "optionen": [{"text": "Lesen, wer lügt", "tag": "[Menschenkenntnis]", "probe": {"id": "menschenkenntnis", "dc": 12}, "erfolg": {"text": "Oda lügt – aber nicht ganz. Sie hat nachts geschöpft. Für ihr Kind, nicht für den Garten. Sie schämt sich.", "weiter": "entscheiden", "folgen": {"flag": ["oda_nacht"]}}, "misserfolg": {"text": "Beide glauben, was sie sagen.", "weiter": "entscheiden"}}, {"text": "Den Brunnen untersuchen", "weiter": "brunnen"}]}, "brunnen": {"ort": "dorf", "text": "Der Brunnenschacht ist tief. Unten glitzert wenig Wasser. Am Seil: frische Fasern, als hätte es jemand nachts benutzt. Und am Rand eine Rinne, die jemand gegraben hat – zum Garten von Berthe!", "minispiel": {"art": "spuren", "schwer": 2, "titel": "Den Brunnen lesen", "erfolg": {"text": "Die Rinne ist frisch. Wer nachts schöpft und das Wasser auf den Weg kippt, legt eine Spur, die zum Nachbarn führt. Jemand wollte, dass es nach Oda aussieht – oder Berthe hat selbst geschöpft und die Spur gelegt.", "weiter": "entscheiden", "folgen": {"flag": ["rinne"]}}, "misserfolg": {"text": "Nasse Erde, ein Seil. Mehr erzählt der Brunnen nicht.", "weiter": "entscheiden"}}, "optionen": []}, "entscheiden": {"ort": "dorf", "text": "Die beiden warten. Das halbe Dorf wartet. Und du bist nur ein Gast.", "optionen": [{"text": "„Die Rinne führt zu Berthe. Wer hat sie gegraben?“", "wenn": {"flag": "rinne"}, "weiter": "ende_rinne"}, {"text": "„Oda hat nachts geschöpft – für ihr Kind. Wer will ihr das vorwerfen?“", "tag": "[Überreden]", "probe": {"id": "ueberreden", "dc": 12}, "erfolg": {"text": "Stille. Dann nickt Berthe, widerwillig. „Für ein Kind. Gut. Aber sag es nächstes Mal.“", "weiter": "ende_kind"}, "misserfolg": {"text": "„Gesetz ist Gesetz“, sagt Berthe. Die Leute murmeln zustimmend.", "weiter": "ende_streit"}, "wenn": {"flag": "oda_nacht"}}, {"text": "„Teilt das Wasser nach Köpfen, nicht nach Gärten.“", "weiter": "ende_regel"}]}, "ende_rinne": {"ort": "dorf", "text": "Berthe wird rot. Sie hat die Rinne gegraben, um Oda loszuwerden, die ihr den Platz am Brunnen streitig macht. Das Dorf lacht über sie, dann vergisst es. Oda bringt dir am Abend einen Kanten Brot – mehr hat sie nicht.", "ende": true, "folgen": {"chronik": ["gast_brunnen", "In einem fremden Dorf habe ich einen Brunnenstreit geschlichtet."], "beute": {"stufe": 1}}}, "ende_kind": {"ort": "dorf", "text": "Die Leute gehen auseinander. Oda weint vor Erleichterung. Berthe brummt. Im Dorf wird man noch lange von dem Fremden reden, der am Brunnen recht gesprochen hat.", "ende": true, "folgen": {"chronik": ["gast_kind", "In einem fremden Dorf habe ich für eine Mutter gesprochen."], "beute": {"stufe": 1}}}, "ende_regel": {"ort": "dorf", "text": "Die Regel ist einfach, und deshalb hält sie. Keine der beiden ist zufrieden, und beide befolgen sie. Der Dorfrat schreibt sie auf ein Brett und hängt es an den Brunnen.", "ende": true, "folgen": {"chronik": ["gast_regel", "In einem fremden Dorf habe ich eine Brunnenregel vorgeschlagen."]}}, "ende_streit": {"ort": "dorf", "text": "Oda muss eine Strafe zahlen. Sie zahlt mit ihrem letzten Huhn. Als du gehst, steht sie am Zaun und sieht dir nach.", "ende": true, "folgen": {"chronik": ["gast_streit", "Ich habe in einem fremden Dorf nicht helfen können."]}}}}}, {"id": "o_gast_elske", "titel": "Der gedeckte Tisch", "kurz": "Eine Frau deckt jeden Abend für ihren Sohn, der nicht zurückkommt. Niemand im Dorf traut sich, mit ihr zu reden.", "schwer": 1, "fundort": "spielerdorf", "def": {"start": "start", "szenen": {"start": {"ort": "dorf", "text": "Am Rand dieses Dorfes steht eine Frau vor einem leeren Haus und redet mit jemandem, der nicht da ist. Die Leute gehen vorbei, ohne hinzusehen. „Elske“, sagt einer dir leise. „Ihr Sohn ist vor einem Jahr zum Söldnerdienst gegangen und nicht zurückgekommen. Sie deckt jeden Abend für ihn den Tisch.“", "optionen": [{"text": "Zu ihr gehen", "weiter": "elske"}, {"text": "Weitergehen", "weiter": "ende_weiter"}]}, "elske": {"ort": "dorf", "text": "Elske lächelt dich an, als hätte sie dich erwartet. „Du kommst von draußen. Hast du meinen Jorin gesehen? Groß, rote Haare, lacht laut.“ Auf dem Tisch hinter ihr: zwei Teller, zwei Becher, ein Brot.", "optionen": [{"text": "Behutsam fragen, was sie zuletzt von ihm gehört hat", "tag": "[Beruhigen]", "probe": {"id": "beruhigen", "dc": 11}, "erfolg": {"text": "„Ein Brief. Im Winter. Er schrieb, er komme im Frühling.“ Sie holt ihn, zerknittert. Unter dem Brief, in fremder Hand, steht etwas, das sie nicht lesen kann: „Gefallen bei Kammwacht. Der Hauptmann.“", "weiter": "brief"}, "misserfolg": {"text": "Sie weicht aus. „Er kommt bald. Ich weiß es.“", "weiter": "warten"}}, {"text": "„Ich habe ihn gesehen.“ (lügen)", "weiter": "luege"}]}, "warten": {"ort": "dorf", "text": "Sie stellt einen dritten Becher hin. Für dich.", "optionen": [{"text": "Mit ihr am Tisch sitzen", "weiter": "brief", "ergebnis": "Ihr esst schweigend. Dann holt sie einen Brief, zerknittert, und legt ihn vor dich hin."}]}, "brief": {"ort": "dorf", "text": "Sie weiß es nicht. Niemand hat es ihr vorgelesen. Oder sie hat nicht zugehört.", "optionen": [{"text": "Ihr vorlesen, was da steht", "weiter": "wahrheit"}, {"text": "Den Brief zusammenfalten und schweigen", "weiter": "ende_schweigen"}]}, "wahrheit": {"ort": "dorf", "text": "Du liest es vor. Elske sitzt lange still. Dann nimmt sie den zweiten Teller vom Tisch und stellt ihn in den Schrank. Ganz langsam. „Ich wusste es“, sagt sie. „Ich wollte nur nicht, dass es jemand sagt.“", "optionen": [{"text": "Bei ihr bleiben, bis sie weinen kann", "tag": "[Beruhigen]", "probe": {"id": "beruhigen", "dc": 12}, "erfolg": {"text": "Sie weint die ganze Nacht. Am Morgen kommen die Nachbarinnen, zum ersten Mal seit einem Jahr. Sie bringen Brot. Sie bleiben.", "weiter": "ende_trauer"}, "misserfolg": {"text": "Sie bittet dich zu gehen. Aber sie sagt danke.", "weiter": "ende_trauer"}}]}, "luege": {"ort": "dorf", "text": "Ihr Gesicht leuchtet auf. „Wo? Wann? Geht es ihm gut?“ Jetzt musst du die Lüge weitertragen.", "optionen": [{"text": "Die Lüge zurücknehmen und ihr die Wahrheit sagen", "weiter": "brief", "ergebnis": "„Verzeih. Ich habe gelogen.“ Ihr Lächeln erlischt nicht gleich. Dann holt sie den Brief."}, {"text": "Weiterlügen: „Er ist im Süden. Er kommt, wenn er kann.“", "weiter": "ende_luege"}]}, "ende_trauer": {"ort": "dorf", "text": "Als du gehst, steht Elske am Fenster und winkt. Auf dem Tisch hinter ihr steht nur noch ein Teller. Ein Nachbar hält dich am Zaun auf. „Wir hätten es ihr sagen müssen“, sagt er. „Wir haben uns nicht getraut.“", "ende": true, "folgen": {"chronik": ["gast_elske", "In einem fremden Dorf habe ich einer Mutter die Wahrheit über ihren Sohn vorgelesen."], "beute": {"stufe": 1, "text": "Elske gibt dir etwas, das Jorin gehörte:"}}}, "ende_schweigen": {"ort": "dorf", "text": "Du gibst ihr den Brief zurück. Sie deckt weiter für zwei. Vielleicht ist das Barmherzigkeit. Vielleicht ist es nur Feigheit mit freundlichem Gesicht.", "ende": true, "folgen": {"chronik": ["gast_elske_schweigen", "Ich habe einer Mutter nicht gesagt, dass ihr Sohn tot ist."]}}, "ende_luege": {"ort": "dorf", "text": "Elske strahlt, als du gehst. Morgen wird sie wieder für zwei decken, und übermorgen, und im Frühling wird sie am Weg stehen. Und du wirst nie wieder hierher kommen können, ohne an sie zu denken.", "ende": true, "folgen": {"chronik": ["gast_elske_luege", "Ich habe einer Mutter gesagt, ihr toter Sohn lebe."]}}, "ende_weiter": {"ort": "dorf", "text": "Du gehst weiter. Hinter dir redet Elske mit dem leeren Haus.", "ende": true}}}}]$q$::jsonb) e
on conflict (id) do update set titel = excluded.titel, beschreibung = excluded.beschreibung, kurz = excluded.kurz, art = excluded.art, schwierigkeit = excluded.schwierigkeit, def = excluded.def, fundort = excluded.fundort;
